function renderPVWorkspace(){
  const products=state.plan.campaign.products,index=Math.max(0,products.findIndex(x=>x.id===state.selectedPVProduct)),product=products[index]||products[0],sku=state.plan.skus[index]||state.plan.skus[0],m=state.plan.metrics;
  const variants=[{name:'PV-1',factor:1.18,rate:.86,yield:-3,setup:1.55,score:72},{name:'PV-2',factor:1.08,rate:.94,yield:-1,setup:1.2,score:82},{name:sku.pv,factor:1,rate:1,yield:0,setup:1,score:94,recommended:true}].filter((x,i,a)=>a.findIndex(y=>y.name===x.name)===i);
  const productCards=products.map((x,i)=>`<button class="pv-product-card ${x.id===product.id?'active':''}" data-pv-product="${x.id}"><i style="background:${x.color}"></i><span><b>${x.name}</b><small>${x.sku} · ${x.line}</small></span><strong>${state.plan.skus[i].pv}</strong><em>${x.recommendedAchievement.toFixed(1)}% target</em></button>`).join('');
  const ranking=products.map((x,i)=>{const s=state.plan.skus[i];return `<button class="pv-ranking-row ${x.id===product.id?'selected':''}" data-pv-product="${x.id}"><span>0${i+1}</span><span><b>${x.name}</b><small>${x.sku} · ${x.category}</small></span><strong>${s.pv}</strong><span>${s.line}</span><span>${usdUnit(s.unit_cost)}</span><span>${fmt(s.rate)}/hr</span><span>${s.yield}%</span><em>+${fmt(x.recommendedVolume-x.currentVolume)}</em><i>›</i></button>`}).join('');
  const options=variants.map((x,i)=>`<article class="pv-option ${x.recommended?'recommended':''}"><header><span>${x.recommended?'RECOMMENDED':`ALTERNATIVE ${i+1}`}</span><b>${x.name}</b><em>${x.recommended?sku.line:product.line}</em></header><div class="pv-option-score" style="--score:${x.score}"><strong>${x.score}</strong><small>decision score</small></div><dl><div><dt>Unit cost</dt><dd>${usdUnit(sku.unit_cost*x.factor)}</dd></div><div><dt>Run rate</dt><dd>${fmt(Math.round(sku.rate*x.rate))}/hr</dd></div><div><dt>Yield</dt><dd>${sku.yield+x.yield}%</dd></div><div><dt>Setup</dt><dd>${(sku.setup*x.setup).toFixed(1)} hrs</dd></div></dl><footer><span>✓ Technically feasible</span><b>${x.recommended?'Selected':'Available'}</b></footer></article>`).join('');
  const profiles=[['Cost efficiency',[82,90,100]],['Throughput',[84,92,100]],['Yield',[sku.yield-3,sku.yield-1,sku.yield]],['Setup efficiency',[66,83,100]],['Capacity fit',[78,86,94]]];
  const lines=state.plan.lines.slice(0,3).map((line,i)=>{const current=line.utilisation?.[0]??[76,71,68][i],recommended=line.utilisation?.[1]??[86,82,80][i];return `<article><header><b>${line.id||products[i].line}</b><span>${products[i].name}</span><strong>${recommended}%</strong></header><div><i style="width:${current}%"><em>${current}%</em></i></div><div><i class="recommended" style="width:${recommended}%"><em>${recommended}%</em></i></div><footer><span>Current</span><span>Recommended</span><b>+${recommended-current} pp</b></footer></article>`}).join('');
  return `<section class="pv-workspace"><div class="pv-hero card"><div><span>PRODUCTION VERSION DECISION</span><h2>${product.name}</h2><p>${product.sku} · ${product.category} · ${product.formula}</p></div><section><small>Recommended route</small><strong>${sku.pv} <i>on ${sku.line}</i></strong><p>${sku.rationale}</p></section><aside><span>Decision confidence</span><b>94%</b><i><em style="width:94%"></em></i><small>Cost, yield, throughput and capacity aligned</small></aside></div><div class="kpi-grid">${kpi('▦','Portfolio Cost Impact',`$${(m.current_cost-m.recommended_cost).toFixed(2)}M`,'estimated plan saving',`↓ ${metricDelta(m.current_cost,m.recommended_cost)}`)}${kpi('◎','PV Decisions',`${products.length} / ${products.length}`,'feasible routes assigned','100% reviewed')}${splitKpi('▥','Target Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`+${m.achievement_gain} pp`)}${splitKpi('◷','Line Utilization',`${m.utilisation_current}%`,`${m.utilisation_recommended}%`,`+${m.utilisation_recommended-m.utilisation_current} pp`)}</div>${panel('Select a launch to inspect',`<div class="pv-product-selector">${productCards}</div>`,'pv-selector-panel','Selection refreshes alternatives, manufacturing evidence and business impact.')}<div class="grid-2 wide-left pv-primary-grid">${panel('PV Decision Portfolio',`<div class="pv-ranking-head"><span>Rank</span><span>Launch / SKU</span><span>PV</span><span>Line</span><span>Unit cost</span><span>Run rate</span><span>Yield</span><span>Volume gain</span><span></span></div><div class="pv-ranking">${ranking}</div>`,'pv-ranking-panel','Ranked by feasible cost, output, quality and capacity fit.')}${panel('Selected Decision',`<div class="pv-decision-brief"><span style="--product:${product.color}">01</span><div><small>WHY ${sku.pv}</small><h3>${sku.rationale}</h3><p>${fmt(product.recommendedVolume-product.currentVolume)} additional feasible units improve target achievement from ${product.currentAchievement.toFixed(1)}% to ${product.recommendedAchievement.toFixed(1)}%.</p></div></div><div class="pv-impact-tiles"><article><span>Volume uplift</span><b>+${fmt(product.recommendedVolume-product.currentVolume)}</b><small>units</small></article><article><span>Unit cost</span><b>${usdUnit(sku.unit_cost)}</b><small>recommended</small></article><article><span>Line fit</span><b>${sku.line}</b><small>validated route</small></article></div><button class="m2-secondary pv-explain" data-jump="explain">Open decision explanation →</button>`,'pv-selected-panel')}</div>${panel(`${product.name} — Production Version Alternatives`,`<div class="pv-options">${options}</div>`,'pv-options-panel','Recommendation highlighted; alternatives remain available for governed review.')}<div class="grid-2 pv-evidence-grid">${panel('Performance Profile',`<div class="pv-profile"><header><span>Metric</span>${variants.map(x=>`<b>${x.name}</b>`).join('')}</header>${profiles.map(row=>`<section><span>${row[0]}</span>${variants.map((x,i)=>`<i><em class="${x.recommended?'recommended':''}" style="width:${row[1][Math.min(i,2)]}%"></em><b>${row[1][Math.min(i,2)]}</b></i>`).join('')}</section>`).join('')}</div>`,'pv-profile-panel','Normalized score (100 = strongest option).')}${panel('Recommendation Drivers',`<div class="pv-drivers">${[['Throughput fit',18.2,92],['Yield advantage',14.6,77],['Line compatibility',12.4,66],['Setup efficiency',9.8,53],['Changeover exposure',-3.5,20]].map(x=>`<article><span>${x[0]}</span><i><em class="${x[1]<0?'negative':''}" style="width:${x[2]}%"></em></i><b>${x[1]>0?'+':''}${x[1]}</b></article>`).join('')}</div><div class="pv-driver-note"><b>Net advantage +51.5</b><span>Operational fit outweighs manageable changeover exposure.</span></div>`,'pv-drivers-panel','Contribution to the selected decision score.')}</div><div class="grid-2 wide-left pv-bottom-grid">${panel('Capacity Allocation by Line',`<div class="pv-capacity"><div class="strategy-axis"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div>${lines}</div>`,'pv-capacity-panel','Recommended routes remain within the manufacturing envelope.')}${panel('Decision Guardrails',`<div class="pv-guardrails"><article><i>✓</i><p><b>Technical route eligible</b><small>Formula, package and filling technology match.</small></p></article><article><i>✓</i><p><b>Capacity remains feasible</b><small>Load stays below the planning threshold.</small></p></article><article><i>✓</i><p><b>Quality protected</b><small>Expected yield is within validated range.</small></p></article><article class="attention"><i>!</i><p><b>Review trigger</b><small>Re-evaluate if demand changes by more than 15%.</small></p></article></div>`,'pv-guardrail-panel','Evidence retained for manufacturing review.')}</div>${panel('Continue the Planning Decision',`<div class="pv-next-actions"><button data-jump="moq"><span>01</span><p><b>Set line-level MOQ</b><small>Balance setup cost and inventory</small></p><i>→</i></button><button data-jump="scenario"><span>02</span><p><b>Manufacturing review</b><small>Stress-test constraints</small></p><i>→</i></button><button data-jump="explain"><span>03</span><p><b>Explain this decision</b><small>Inspect reasoning and evidence</small></p><i>→</i></button><button data-jump="review"><span>04</span><p><b>Review & approve</b><small>Prepare final recommendation</small></p><i>→</i></button></div>`,'pv-next-panel')}</section>${footer()}`
}

function footer(){return `<footer class="m2-footer"><span>Project PULSE <i>|</i> Confidential – For POC Use Only</span><span>Module 2 – Manufacturing Optimisation <i>|</i> v1.2.0</span></footer>`}
function panel(title,body,cls='',subtitle='',actions=''){return `<article class="card panel ${cls}"><div class="panel-head"><div><h3>${title}</h3>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions}</div>${body}</article>`}
function kpi(icon,label,value,detail='',delta='',cls=''){return `<article class="card kpi ${cls}"><span class="kpi-icon">${icon}</span><div><small>${label}</small><strong>${value}</strong>${detail?`<em>${detail}</em>`:''}${delta?`<div class="delta">${delta}</div>`:''}</div></article>`}
function splitKpi(icon,label,current,recommended,delta,unit=''){return `<article class="card kpi"><span class="kpi-icon">${icon}</span><div><small>${label}</small><div class="split-value"><span><b>${current}${unit}</b><em>Current</em></span><i>→</i><span><b class="good">${recommended}${unit}</b><em>Recommended</em></span></div><div class="delta">${delta}</div></div></article>`}
function sequenceLegend(){return `<div class="sequence-legend"><span><i></i>Production</span><span><i></i>Changeover</span><span><i></i>Cleaning</span><span><i></i>Idle</span></div>`}
function sequenceRows(map,lines=Object.keys(map)){return `<div class="week-head"><b>Line</b><b>Week 1</b><b>Week 2</b><b>Week 3</b><b>Week 4</b></div><div class="sequence">${lines.map(line=>`<div class="sequence-row"><b>${line}</b><div class="sequence-track">${map[line].map((p,i)=>`<span class="sequence-block">${p}</span>${i<map[line].length-1?'<i class="sequence-event"></i><i class="sequence-event clean"></i><i class="sequence-event idle"></i>':''}`).join('')}</div></div>`).join('')}</div>`}
function barChart(groups,max){return `<div class="bar-chart">${groups.map(g=>`<div class="bar-pair"><i style="height:${g[1]/max*100}%"><b>${g[1]}</b></i><i class="orange" style="height:${g[2]/max*100}%"><b>${g[2]}</b></i><span>${g[0]}</span></div>`).join('')}</div>`}
function costBreakdownChart(){const m=state.plan.metrics,current=m.current_cost,total=m.recommended_cost,rows=[['Production / Run',Number((current*.5).toFixed(2)),Number((total*.54).toFixed(2))],['Setup & Changeover',Number((current*.19).toFixed(2)),Number((total*.12).toFixed(2))],['Inventory Holding',Number((m.inventory_current).toFixed(2)),Number((m.inventory_recommended).toFixed(2))],['Labour',Number((current*.05).toFixed(2)),Number((total*.055).toFixed(2))],['Other & Indirects',Number((current*.04).toFixed(2)),Number((total*.035).toFixed(2))]],max=Math.max(...rows.flatMap(row=>row.slice(1)));return `<div class="cost-chart-head"><div><small>Current plan</small><strong>$${current}M</strong></div><span>→</span><div><small>Recommended</small><strong class="good">$${total}M</strong></div><em class="good">$${(current-total).toFixed(2)}M saved</em></div><div class="cost-compare-legend"><span><i></i>Current</span><span><i></i>Recommended</span></div><div class="cost-compare-chart">${rows.map(row=>`<div class="cost-compare-row"><b>${row[0]}</b><div><span style="width:${row[1]/max*100}%"><em>$${row[1]}M</em></span></div><div><span style="width:${row[2]/max*100}%"><em>$${row[2]}M</em></span></div></div>`).join('')}</div>`}
function enhanceCostBreakdown(){const heading=$$('.panel-head h3').find(node=>node.textContent.includes('Cost Breakdown – Current vs Recommended'));if(!heading)return;const card=heading.closest('.panel');$$(':scope > :not(.panel-head)',card).forEach(node=>node.remove());card.insertAdjacentHTML('beforeend',costBreakdownChart())}
function enhanceStrategyOverview(){const m=state.plan.metrics,headings=$$('.panel-head h3');const costHeading=headings.find(node=>node.textContent.includes('Cost Comparison'));if(costHeading){const card=costHeading.closest('.panel');card.classList.add('strategy-chart-card');$$(':scope > :not(.panel-head)',card).forEach(node=>node.remove());card.insertAdjacentHTML('beforeend',costBreakdownChart())}const changeHeading=headings.find(node=>node.textContent.includes('Changeovers by Line'));if(changeHeading){const card=changeHeading.closest('.panel');card.classList.add('strategy-chart-card');card.querySelector('.horizontal-bars')?.insertAdjacentHTML('beforebegin',`<div class="changeover-summary"><div><small>Current plan</small><strong>68</strong></div><span>→</span><div><small>Recommended</small><strong class="good">${m.changeovers_recommended}</strong></div><em class="good">${68-m.changeovers_recommended} fewer events</em></div>`)}const takeawayHeading=headings.find(node=>node.textContent.includes('Key Takeaways'));if(takeawayHeading){const card=takeawayHeading.closest('.panel');card.classList.add('strategy-full-width','strategy-command-center');$$(':scope > :not(.panel-head)',card).forEach(node=>node.remove());card.insertAdjacentHTML('beforeend',`<div class="strategy-takeaway-layout"><section class="strategy-outcome"><span>PORTFOLIO VALUE</span><strong>$${(12.4-m.recommended_cost).toFixed(2)}M</strong><b>estimated savings</b><div><i style="--value:${Math.min(100,Math.round((12.4-m.recommended_cost)/2.5*100))}%"></i></div><small>${selectedLaunches().length} launch${selectedLaunches().length===1?'':'es'} · ${state.plan.launch_context.label}</small></section><section><h4>Why this plan wins</h4><ul class="check-list"><li>${metricDelta(12.4,m.recommended_cost)} lower total order cost</li><li>${68-m.changeovers_recommended} fewer changeovers across the network</li><li>${m.utilisation_recommended-72} pp higher line utilization</li><li>$${(3.2-m.inventory_recommended).toFixed(2)}M less average inventory</li></ul></section><section><h4>Continue the decision</h4><div class="next-action-grid"><button data-jump="pv"><span>01</span><b>Review PV decisions</b><small>Validate versions by launch</small></button><button data-jump="moq"><span>02</span><b>Confirm MOQ</b><small>Balance setup and inventory</small></button><button data-jump="scenario"><span>03</span><b>Manufacturing review</b><small>Adjust constraints and resolve</small></button><button data-jump="review"><span>04</span><b>Review & approve</b><small>Complete final validation</small></button></div></section></div>`)}}
function enhanceManufacturingReview(){if(!state.previousMetrics)return;const before=state.previousMetrics,after=state.plan.metrics,banner=$('.review-banner');if(!banner)return;banner.insertAdjacentHTML('afterend',`<div class="resolution-delta"><div><span>LAST RESOLUTION CHANGE</span><b>${state.plan.launch_context.label}</b></div>${[['Target achievement',`${before.recommended_achievement}%`,`${after.recommended_achievement}%`],['Total cost',`$${before.recommended_cost}M`,`$${after.recommended_cost}M`],['Changeovers',before.changeovers_recommended,after.changeovers_recommended],['Line utilization',`${before.utilisation_recommended}%`,`${after.utilisation_recommended}%`]].map(item=>`<section><small>${item[0]}</small><p><del>${item[1]}</del><i>→</i><strong>${item[2]}</strong></p></section>`).join('')}</div>`)}
function enhanceCampaignStrategy(){const m=state.plan.metrics,grid=$('#m2-content .kpi-grid');if(grid)grid.innerHTML=splitKpi('◎','Volume Target Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`↑ ${m.achievement_gain} pp`)+splitKpi('▥','Achieved Volume',`${fmt(m.current_volume)} units`,`${fmt(m.recommended_volume)} units`,`+${fmt(m.recommended_volume-m.current_volume)} units`)+splitKpi('▤','Manufacturing Utilization',`${m.utilisation_current}%`,`${m.utilisation_recommended}%`,`${m.utilisation_recommended-m.utilisation_current>=0?'+':''}${m.utilisation_recommended-m.utilisation_current} pp`)+splitKpi('▦','Production Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`${m.recommended_cost<=m.current_cost?'↓':'↑'} ${metricDelta(m.current_cost,m.recommended_cost)}`);const summary=$('.changeover-summary');if(summary)summary.innerHTML=`<div><small>Current plan</small><strong>${m.changeovers_current}</strong></div><span>→</span><div><small>Recommended</small><strong class="good">${m.changeovers_recommended}</strong></div><em>${m.changeovers_current-m.changeovers_recommended} fewer events</em>`;const command=$('.strategy-command-center');if(command){const body=command.querySelector('.strategy-takeaway-layout');if(body)body.innerHTML=`<section class="strategy-outcome"><span>VOLUME TARGET ACHIEVEMENT</span><strong>${m.recommended_achievement}%</strong><b>recommended four-week plan</b><div><i style="--value:${m.recommended_achievement}%"></i></div><small>${fmt(m.recommended_volume)} of ${fmt(m.target_volume)} target units</small></section><section><h4>Why the plan performs better</h4><ul class="check-list"><li>${fmt(m.recommended_volume-m.current_volume)} additional feasible units planned</li><li>${m.changeovers_current-m.changeovers_recommended} fewer changeovers release productive time</li><li>PV and line assignments improve throughput within capacity</li><li>Target volume remains a hard ceiling for every product</li></ul></section><section><h4>Operational trade-offs</h4><ul class="tradeoff-list"><li><span>Inventory</span><b class="${m.inventory_recommended>m.inventory_current?'warn':'good'}">$${m.inventory_current}M → $${m.inventory_recommended}M</b></li><li><span>Setup time</span><b>${m.setup_current} → ${m.setup_recommended} hrs</b></li><li><span>Production cost</span><b>$${m.current_cost}M → $${m.recommended_cost}M</b></li></ul><button class="m2-secondary" data-jump="pv">Continue to PV Prioritization →</button></section>`}const products=state.plan.campaign.products,footer=$('.m2-footer');footer?.insertAdjacentHTML('beforebegin',panel('Volume Achievement by Product',`<div class="campaign-achievement-table"><header><span>Product</span><span>Target</span><span>Current Plan</span><span>Recommended Plan</span><span>Achievement</span></header>${products.map(item=>`<div><b>${item.name}<small>${item.sku} · ${item.line}</small></b><span>${fmt(item.targetVolume)}</span><span>${fmt(item.currentVolume)} <small>${item.currentAchievement.toFixed(1)}%</small></span><span>${fmt(item.recommendedVolume)} <small>${item.recommendedAchievement.toFixed(1)}%</small></span><i><em style="width:${item.recommendedAchievement}%"></em></i></div>`).join('')}</div>`,'campaign-achievement-panel','Current manufacturing baseline compared with the feasible recommendation.'))}
function replacePanelBody(title,html,classes=''){const heading=$$('.panel-head h3').find(node=>node.textContent.includes(title));if(!heading)return;const card=heading.closest('.panel');classes.split(' ').filter(Boolean).forEach(name=>card.classList.add(name));$$(':scope > :not(.panel-head)',card).forEach(node=>node.remove());card.insertAdjacentHTML('beforeend',html)}
function enhancePVFooter(){const m=state.plan.metrics,switches=state.plan.skus;replacePanelBody('PV Switch Impact Summary',`<div class="impact-hero"><div class="impact-ring" style="--score:${m.recommended_achievement}"><strong>${switches.length}</strong><small>PV decisions</small></div><div class="impact-outcomes"><section><span>Campaign coverage</span><b>100%</b><i><em style="width:100%"></em></i><small>All 3 active products assigned</small></section><section><span>Volume achievement</span><b>${m.recommended_achievement}%</b><i><em style="width:${m.recommended_achievement}%"></em></i><small>+${m.achievement_gain} pp vs current plan</small></section><section><span>Manufacturing utilization</span><b>${m.utilisation_recommended}%</b><i><em style="width:${m.utilisation_recommended}%"></em></i><small>${m.utilisation_current}% → ${m.utilisation_recommended}%</small></section></div></div>`,'decision-panel pv-impact-panel');replacePanelBody('Top PV Switches by Impact',`<div class="ranked-impact-list">${switches.map((sku,index)=>`<div><span class="impact-rank">0${index+1}</span><p><b>${sku.sku}</b><small>${sku.product} · ${sku.line}</small></p><em><i style="width:${100-index*20}%"></i></em><strong class="good">+${fmt(state.plan.campaign.products[index].recommendedVolume-state.plan.campaign.products[index].currentVolume)}</strong></div>`).join('')}</div>`,'decision-panel ranked-impact-panel');replacePanelBody('Quick Actions',`<div class="decision-actions"><button data-jump="explain"><span>◎</span><p><b>Explain a PV decision</b><small>See volume, yield and capacity drivers</small></p><i>→</i></button><button data-jump="scenario"><span>↻</span><p><b>Test an alternative</b><small>Adjust supported manufacturing inputs</small></p><i>→</i></button><button data-jump="strategy"><span>▥</span><p><b>Compare campaign impact</b><small>Return to the Strategic Overview</small></p><i>→</i></button></div>`,'decision-panel quick-decision-panel')}
function enhanceCostFooter(){const m=state.plan.metrics,saving=(m.current_cost-m.recommended_cost).toFixed(2),inventoryDirection=m.inventory_recommended>m.inventory_current?'increases as the plan closes the volume gap':'decreases through the recommended MOQ mix';replacePanelBody('Key Insights',`<div class="insight-spotlight"><section><small>NET PLAN SAVING</small><strong>$${saving}M</strong><span>${metricDelta(m.current_cost,m.recommended_cost)} below the campaign baseline</span></section><ul><li><b>Setup efficiency</b><span>${m.setup_current-m.setup_recommended} setup hours are released through sequencing and MOQ decisions.</span></li><li><b>Inventory trade-off</b><span>Average inventory ${inventoryDirection}: $${m.inventory_current}M → $${m.inventory_recommended}M.</span></li><li><b>Volume value</b><span>The plan schedules ${fmt(m.recommended_volume-m.current_volume)} additional feasible units without breaching targets.</span></li></ul></div>`,'decision-panel cost-insight-panel');replacePanelBody('Cost Assumptions',`<div class="assumption-grid">${[['Labor rate','$1,200','per hour'],['Line operations','$800','per hour'],['Standard clean','$50K','per event'],['Full clean','$120K','per event'],['Inventory holding','18%','per annum']].map((item,index)=>`<div><span>${item[0]}</span><b>${item[1]}</b><small>${item[2]}</small><i class="${index<2?'verified':''}">${index<2?'Validated':'Planning default'}</i></div>`).join('')}</div><p class="assumption-note">Cost assumptions are applied consistently to the same three campaign products.</p>`,'decision-panel assumptions-panel');replacePanelBody('Quick Actions',`<div class="decision-actions cost-actions"><button data-jump="settings"><span>⚙</span><p><b>Review cost parameters</b><small>Validate rates and holding assumptions</small></p><i>→</i></button><button data-jump="scenario"><span>◌</span><p><b>Stress-test the plan</b><small>Compare supported manufacturing changes</small></p><i>→</i></button><button data-jump="review"><span>⇩</span><p><b>Prepare cost evidence</b><small>Continue to review and approval</small></p><i>→</i></button></div>`,'decision-panel quick-decision-panel')}
function enhanceConstraintFooter(){const active=state.plan.constraints.filter(item=>item.active).length;replacePanelBody('Key Takeaways',`<div class="constraint-outcome"><section><span>COMPLIANCE STATUS</span><strong>0</strong><b>plan violations</b><small>${active} active rules applied</small></section><div><article><i>✓</i><p><b>Governed adjustments</b><small>Only approved rule types and supported values can change.</small></p></article><article><i>✓</i><p><b>Feasible recommendation</b><small>Every active manufacturing constraint is respected.</small></p></article><article><i>✓</i><p><b>Connected outputs</b><small>Resolve Plan refreshes KPIs, sequence, cost and approval evidence.</small></p></article></div></div>`,'decision-panel constraint-takeaway-panel');replacePanelBody('Next Steps',`<div class="workflow-steps"><button><span>01</span><p><b>Review rule values</b><small>Confirm active parameters with operations</small></p><i>Current</i></button><button id="constraint-resolve-shortcut"><span>02</span><p><b>Resolve the plan</b><small>Apply changes to the recommendation</small></p><i>Next</i></button><button data-jump="scenario"><span>03</span><p><b>Manufacturing review</b><small>Compare the before and after impact</small></p><i>→</i></button><button data-jump="review"><span>04</span><p><b>Review & approve</b><small>Complete cross-functional validation</small></p><i>→</i></button></div>`,'decision-panel constraint-steps-panel')}
function refreshViewKpis(){const grid=$('#m2-content .kpi-grid');if(!grid)return;const m=state.plan.metrics,launches=selectedLaunches(),selectedSkus=state.plan.skus.slice(0,launches.length),avg=(values)=>values.reduce((sum,value)=>sum+value,0)/Math.max(1,values.length);if(state.view==='pv')grid.innerHTML=kpi('⚙','Plan Cost Impact',`$${(m.current_cost-m.recommended_cost).toFixed(2)}M`,'while increasing feasible output',`${m.recommended_cost<=m.current_cost?'↓':'↑'} ${metricDelta(m.current_cost,m.recommended_cost)}`)+kpi('⌘','Campaign PV Decisions',`${launches.length} / ${launches.length}`,'Active products assigned','100% reviewed')+splitKpi('▥','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`+${m.achievement_gain} pp`)+splitKpi('◷','Capacity Utilisation',`${m.utilisation_current}%`,`${m.utilisation_recommended}%`,`${m.utilisation_recommended-m.utilisation_current>=0?'+':''}${m.utilisation_recommended-m.utilisation_current} pp`);if(state.view==='moq'){const averageCurrent=Math.round(avg(state.plan.skus.map(item=>item.moq[0]))/1000)*1000,averageRecommended=Math.round(avg(state.plan.skus.map(item=>item.moq[1]))/1000)*1000,setupCost=Number((2.1*m.setup_recommended/m.setup_current).toFixed(2));grid.innerHTML=splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,`${m.inventory_recommended>m.inventory_current?'↑':'↓'} ${metricDelta(m.inventory_current,m.inventory_recommended)}`)+splitKpi('▦','Setup Cost','$2.1M',`$${setupCost}M`,`↓ ${metricDelta(2.1,setupCost)}`)+splitKpi('▧','Average MOQ',fmt(averageCurrent),fmt(averageRecommended),state.moqMode==='fixed'?'Fixed to marketing target':'Optimized by product')}if(state.view==='campaign')grid.innerHTML=splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`↑ ${m.achievement_gain} pp`)+splitKpi('⇄','Total Changeovers',m.changeovers_current,m.changeovers_recommended,`↓ ${m.changeovers_current-m.changeovers_recommended} events`)+splitKpi('◷','Total Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`↓ ${m.setup_current-m.setup_recommended} hrs`)+splitKpi('▥','Achieved Volume',fmt(m.current_volume),fmt(m.recommended_volume),`+${fmt(m.recommended_volume-m.current_volume)} units`);if(state.view==='cost'){const setup=Number((2.1*m.setup_recommended/m.setup_current).toFixed(2));grid.innerHTML=splitKpi('▦','Total Order Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`${m.recommended_cost<=m.current_cost?'↓':'↑'} ${metricDelta(m.current_cost,m.recommended_cost)}`)+splitKpi('⚙','Setup Cost','$2.1M',`$${setup}M`,`↓ ${metricDelta(2.1,setup)}`)+splitKpi('◇','Inventory Holding Cost',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,`${m.inventory_recommended>m.inventory_current?'↑':'↓'} ${metricDelta(m.inventory_current,m.inventory_recommended)}`)+splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`+${m.achievement_gain} pp`)}}
function planRows(){return state.plan.lines.map(l=>`<tr><td><b>${l.line}</b></td><td>${l.eligible_skus}</td><td>${l.hours.join(' &nbsp; | &nbsp; ')}</td><td>${l.utilisation.join('% &nbsp; | &nbsp; ')}%</td><td>${l.changeovers.join(' &nbsp; | &nbsp; ')}</td><td>${l.cost.join(' &nbsp; | &nbsp; ')}</td><td>${l.change}</td></tr>`).join('')}
function metricDelta(current,recommended){return `${Math.abs((1-recommended/current)*100).toFixed(1)}%`}

function selectedLaunches(){return LAUNCHES.filter(item=>state.selectedLaunches.has(item.id))}
function customLaunchFromForm(form){
  const data=new FormData(form),formula=String(data.get('formula')),category=String(data.get('category')),volume=Math.max(10000,Number(data.get('volume'))||100000),key=`${category} ${formula}`.toLowerCase();
  const archetype=key.includes('mascara')?LAUNCHES.find(x=>x.id==='mascara'):key.includes('foundation')?LAUNCHES.find(x=>x.id==='foundation'):LAUNCHES.find(x=>x.id==='hydrating');
  const requestedLine=String(data.get('line')||''),line=requestedLine==='No preference'||!requestedLine?archetype.line:requestedLine,moq=Math.round(Math.max(15000,Math.min(65000,volume/10))/1000)*1000;
  return {id:`custom-${Date.now()}`,sku:String(data.get('sku')).trim().toUpperCase(),name:String(data.get('name')).trim(),category,formula,targetVolume:volume,targetMoq:moq,currentVolume:0,currentMoq:moq,volume:`${Math.round(volume/1000)}K units`,line,pv:archetype.pv,moq,color:'#ff5800',launchDate:String(data.get('date')),priority:String(data.get('priority'))};
}
function clone(value){return JSON.parse(JSON.stringify(value))}
function applyLaunchScenario(source,variant=state.solutionVariant,options=state.reviewOptions){
  const plan=clone(source),products=selectedLaunches(),m=plan.metrics,moqAdjustment=Number(options.moq_adjustment||0)/100,capacity=Number(options.capacity||90);
  const variants=[
    {label:'Balanced recommendation',volumeFactor:1,costOffset:0,changeovers:14,setup:112,utilisation:84},
    {label:'Efficiency-focused solution',volumeFactor:.96,costOffset:-.24,changeovers:12,setup:104,utilisation:86},
    {label:'Resilience-focused solution',volumeFactor:.92,costOffset:.16,changeovers:15,setup:118,utilisation:81}
  ],choice=variants[variant%variants.length],linePenalty=options.line_constraint==='Standard availability'?0:1,capacityFactor=Math.min(1,Math.max(.78,capacity/90));
  const results=products.map((item,index)=>{const target=Math.max(1,Number(item.targetVolume)),current=Math.min(target,Math.max(0,Number(item.currentVolume))),targetMoq=Math.min(target,Math.max(1000,Number(item.targetMoq))),currentMoq=Math.min(target,Math.max(1000,Number(item.currentMoq)));let recommendedMoq=state.moqMode==='fixed'?targetMoq:Math.round(Math.max(1000,targetMoq*(1+moqAdjustment))/1000)*1000;recommendedMoq=Math.min(target,recommendedMoq);const theoretical=Math.floor(target/recommendedMoq)*recommendedMoq,feasible=Math.floor(theoretical*choice.volumeFactor*capacityFactor/recommendedMoq)*recommendedMoq,recommended=Math.min(target,Math.max(current,feasible));return {...item,targetVolume:target,currentVolume:current,targetMoq,currentMoq,recommendedMoq,recommendedVolume:recommended,currentAchievement:Math.min(100,current/target*100),recommendedAchievement:Math.min(100,recommended/target*100),index}});
  const totalTarget=results.reduce((sum,item)=>sum+item.targetVolume,0),currentTotal=results.reduce((sum,item)=>sum+item.currentVolume,0),recommendedTotal=results.reduce((sum,item)=>sum+item.recommendedVolume,0),volumeGain=recommendedTotal-currentTotal;
  m.current_cost=12.4;m.current_volume=currentTotal;m.recommended_volume=recommendedTotal;m.target_volume=totalTarget;m.current_achievement=Number((currentTotal/totalTarget*100).toFixed(1));m.recommended_achievement=Number((recommendedTotal/totalTarget*100).toFixed(1));m.achievement_gain=Number((m.recommended_achievement-m.current_achievement).toFixed(1));
  m.changeovers_current=18;m.changeovers_recommended=choice.changeovers+linePenalty;m.setup_current=142;m.setup_recommended=choice.setup+linePenalty*4;m.utilisation_current=72;m.utilisation_recommended=Math.min(capacity,choice.utilisation-linePenalty);m.inventory_current=3.2;m.inventory_recommended=Number((3.2+(recommendedTotal-currentTotal)/1000000*.42+(state.moqMode==='adjustable'?.08:0)).toFixed(2));m.recommended_cost=Number((12.4+volumeGain/1000000*.45-1.32+choice.costOffset+(options.strict_due_dates?.12:0)).toFixed(2));
  const lineMap={F04:{current:[320,338],util:[76,84],changes:[8,4],cost:[4.4,3.9]},F07:{current:[280,316],util:[69,82],changes:[6,4],cost:[4.1,3.7]},F02:{current:[260,302],util:[67,80],changes:[4,choice.changeovers-8],cost:[3.9,Number((m.recommended_cost-7.6).toFixed(2))]}};
  plan.lines=Object.entries(lineMap).map(([line,data])=>({line,eligible_skus:results.filter(item=>item.line===line).length,hours:data.current,utilisation:data.util.map((value,i)=>i?Math.min(capacity,value):value),changeovers:data.changes,cost:data.cost,change:line==='F04'?'Dedicated lotion campaign and larger batches':line==='F07'?'Foundation moved to its preferred PV and line':'Mascara runs consolidated into fewer campaigns'}));
  plan.skus=results.map((item,index)=>({sku:item.sku,product:item.name,pv:item.pv,alternatives:item.pv==='PV-3'?'PV-1, PV-2':'PV-2, PV-3',line:item.line,unit_cost:[7.3,8.1,8.6][index],rate:[600,560,480][index],yield:[98,97,96][index],total_cost:Number((item.recommendedVolume*[7.3,8.1,8.6][index]/100000).toFixed(1)),delta:[-18,-14,-9][index],moq:[item.currentMoq,item.recommendedMoq],setup:[70000,82000,95000][index],holding:[.52,.58,.64][index],rationale:`Improves ${item.name} target achievement without exceeding ${fmt(item.targetVolume)} units`}));
  plan.sequences={current:{F04:['Foundation','New Hydrating Lotion','Foundation','New Hydrating Lotion'],F07:['Foundation','Foundation','Foundation','Foundation'],F02:['Mascara','Mascara','Mascara','Mascara']},recommended:{F04:['New Hydrating Lotion','New Hydrating Lotion','New Hydrating Lotion','New Hydrating Lotion'],F07:['Foundation','Foundation','Foundation','Foundation'],F02:['Mascara','Mascara','Mascara','Mascara']}};
  plan.campaign={products:results,totalTarget,currentTotal,recommendedTotal,currentAchievement:m.current_achievement,recommendedAchievement:m.recommended_achievement};
  plan.launch_context={ids:products.map(item=>item.id),count:products.length,names:products.map(item=>item.name),label:choice.label,revision:variant};
  plan.scenario={name:choice.label,moq_adjustment:Number(options.moq_adjustment||0),active_constraints:plan.constraints.filter(c=>c.active).length,strict_due_dates:Boolean(options.strict_due_dates)};
  return plan;
}
function launchContextBar(){const products=selectedLaunches(),context=state.plan.launch_context;return `<div class="launch-context"><div><span>ACTIVE FOUR-WEEK CAMPAIGN</span><b>${products.map(item=>item.name).join(' · ')}</b><small>${state.plan.metrics.recommended_achievement}% target achievement · ${context?.label||'Balanced recommendation'}</small></div><button class="m2-secondary" data-jump="launch">Edit Campaign Brief</button></div>`}
function decisionStrip(area){const products=selectedLaunches(),first=state.plan.skus[0];const copy={pv:`${first.product} is assigned to ${first.pv} on ${first.line}; all three active campaign products are shown.`,moq:`Recommended MOQs improve feasible output while keeping production at or below each target volume.`,campaign:`The recommended sequence contains only ${products.map(item=>item.name).join(', ')} for the active four-week campaign.`,explain:`Drivers and constraint evidence reflect the active three-product campaign and ${state.plan.launch_context.label.toLowerCase()}.`}[area];return `<div class="decision-strip"><span>${area==='pv'?'PV':area==='moq'?'MOQ':area==='campaign'?'SEQUENCE':'EXPLANATION'} UPDATE</span><b>${copy}</b></div>`}

function renderLaunchBrief(){const active=selectedLaunches(),volume=active.reduce((sum,item)=>sum+Number(item.volume.replace(/[^0-9.]/g,'')),0);return `<section class="launch-intro card"><div><span>MODULE 1 → MODULE 2</span><h2>Choose launches to optimize together</h2><p>Select pre-filled launches or create a new launch, then optimize the portfolio across capacity, sequencing, MOQ, and cost.</p></div><div class="launch-selection-summary"><strong>${active.length}</strong><span>launch${active.length===1?'':'es'} selected</span><small>${volume}K planned units</small></div></section><div class="launch-grid">${LAUNCHES.map(item=>`<button type="button" class="launch-card card ${state.selectedLaunches.has(item.id)?'selected':''} ${state.lastLaunchId===item.id?'just-selected':''}" data-launch-id="${item.id}" aria-pressed="${state.selectedLaunches.has(item.id)}"><span class="launch-check">${state.selectedLaunches.has(item.id)?'✓':'+'}</span><span class="launch-card-loader"><i></i><small>Updating portfolio</small></span><i style="--launch-color:${item.color}"></i><div><small>${item.type}${item.priority?` · ${item.priority} priority`:''}</small><h3>${item.name}</h3><p>${item.sku} · ${item.category} · ${item.formula}</p>${item.launchDate?`<p class="launch-date">Launch ${new Date(`${item.launchDate}T00:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</p>`:''}</div><dl><div><dt>Volume</dt><dd>${item.volume}</dd></div><div><dt>Preferred line</dt><dd>${item.line}</dd></div><div><dt>PV</dt><dd>${item.pv}</dd></div><div><dt>Target MOQ</dt><dd>${fmt(item.moq)}</dd></div></dl></button>`).join('')}<button type="button" class="launch-card create-launch-card card" id="create-launch"><span class="create-launch-plus">+</span><div><small>ADD TO PORTFOLIO</small><h3>Create New Launch</h3><p>Enter launch timing, product attributes, volume, and manufacturing preference.</p></div><span class="create-launch-cta">Define launch →</span></button></div><div class="launch-actions card"><div><b>Selected portfolio</b><p>${active.map(item=>item.name).join(', ')}</p></div><button class="m2-primary" id="apply-launches">Build Manufacturing Plan →</button></div><div class="grid-2" style="margin-top:10px">${panel('How selection is used','<ul class="check-list"><li>Loads precomputed PV and MOQ recommendations</li><li>Updates line capacity and campaign sequencing</li><li>Recalculates total cost, changeovers, utilization, and inventory</li></ul>')}${panel('Portfolio planning','<p>Custom launches use the closest synthetic manufacturing archetype so they participate in the same interactive planning flow as the pre-filled launches.</p>')}</div><div class="launch-drawer-shell hidden" id="launch-drawer"><button class="launch-drawer-backdrop" id="close-launch-drawer" aria-label="Close new launch form"></button><aside class="launch-drawer"><div class="launch-drawer-head"><div><small>NEW PORTFOLIO INPUT</small><h2>Create New Launch</h2><p>Add a launch for this planning session.</p></div><button type="button" id="close-launch-drawer-x" aria-label="Close">×</button></div><form id="new-launch-form"><div class="drawer-form"><label>Launch name <span>*</span><input name="name" required placeholder="e.g. Renewal Night Cream"></label><label>Temporary SKU <span>*</span><input name="sku" required placeholder="NPL-SKIN-900"></label><label>Planned launch date <span>*</span><input name="date" type="date" required></label><label>Priority<select name="priority"><option>High</option><option selected>Medium</option><option>Low</option></select></label><label>Product category<select name="category"><option>Skincare</option><option>Serum</option><option>Mascara</option><option>Foundation</option><option>Lip Gloss</option><option>Cleanser</option></select></label><label>Formula / product type<select name="formula"><option>Lotion</option><option>Serum</option><option>Gel</option><option>Mascara</option><option>Cream</option><option>Liquid</option></select></label><label>Forecast volume <span>*</span><div class="input-suffix"><input name="volume" type="number" min="10000" step="1000" value="250000" required><b>units</b></div></label><label>Preferred line<select name="line"><option>F04</option><option>F07</option><option>F02</option><option>F03</option><option>F05</option><option>No preference</option></select></label></div><div class="drawer-note"><b>Synthetic planning behavior</b><p>The POC maps this launch to the closest precomputed scenario using category, formula, volume, and line preference.</p></div><div class="drawer-actions"><button type="button" class="m2-secondary" id="cancel-new-launch">Cancel</button><button type="submit" class="m2-primary">Add Launch to Portfolio</button></div></form></aside></div>${footer()}`}
function campaignAchievement(current,target){return Math.min(100,Math.max(0,current/Math.max(1,target)*100))}
function campaignDraftDrawer(){return `<div class="launch-drawer-shell hidden" id="launch-drawer"><button class="launch-drawer-backdrop" id="close-launch-drawer" aria-label="Close new campaign form"></button><aside class="launch-drawer"><div class="launch-drawer-head"><div><small>FUTURE CAMPAIGN</small><h2>Create New Campaign</h2><p>Capture a future marketing request without changing the active four-week plan.</p></div><button type="button" id="close-launch-drawer-x" aria-label="Close">×</button></div><form id="new-launch-form"><div class="drawer-form"><label>Campaign / product name <span>*</span><input name="name" required placeholder="e.g. Renewal Night Cream"></label><label>Temporary SKU <span>*</span><input name="sku" required placeholder="NPL-SKIN-900"></label><label>Planned launch date <span>*</span><input name="date" type="date" required></label><label>Priority<select name="priority"><option>High</option><option selected>Medium</option><option>Low</option></select></label><label>Product category<select name="category"><option>Skincare</option><option>Foundation</option><option>Mascara</option><option>Serum</option></select></label><label>Formula / product type<select name="formula"><option>Lotion</option><option>Liquid Foundation</option><option>Mascara</option><option>Serum</option></select></label><label>Target volume <span>*</span><div class="input-suffix"><input name="volume" type="number" min="10000" step="1000" value="250000" required><b>units</b></div></label><label>Preferred line<select name="line"><option>F04</option><option>F07</option><option>F02</option><option>No preference</option></select></label></div><div class="drawer-note"><b>Saved separately</b><p>This creates a future campaign draft. The active October four-week plan remains limited to Hydrating Lotion, Foundation, and Mascara.</p></div><div class="drawer-actions"><button type="button" class="m2-secondary" id="cancel-new-launch">Cancel</button><button type="submit" class="m2-primary">Save Campaign Draft</button></div></form></aside></div>`}
function renderCampaignBrief(){const totalTarget=LAUNCHES.reduce((sum,item)=>sum+item.targetVolume,0),totalCurrent=LAUNCHES.reduce((sum,item)=>sum+Math.min(item.currentVolume,item.targetVolume),0),overall=campaignAchievement(totalCurrent,totalTarget);return `<section class="campaign-brief-head card"><div><span>MARKETING REQUIREMENTS · NEXT FOUR WEEKS</span><h2>Campaign Brief</h2><p>Compare marketing targets with the current manufacturing plan, then optimize PV, line assignment, MOQ, and sequence.</p></div><label>Active campaign<select id="campaign-selector"><option>October 2026 · Marketing Requirements</option></select></label><section><small>Current volume target achievement</small><strong id="campaign-overall-value">${overall.toFixed(1)}%</strong><div><i id="campaign-overall-bar" style="width:${overall}%"></i></div><span id="campaign-overall-units">${fmt(totalCurrent)} of ${fmt(totalTarget)} units</span></section></section><div class="campaign-product-grid">${LAUNCHES.map(item=>{const achievement=campaignAchievement(item.currentVolume,item.targetVolume);return `<article class="card campaign-product-card" data-campaign-product="${item.id}"><header><i style="background:${item.color}"></i><div><small>${item.sku} · ${item.line}</small><h3>${item.name}</h3><p>${item.category} · ${item.formula}</p></div><span>${achievement.toFixed(1)}%</span></header><div class="campaign-input-grid"><label>Target Volume<div><input type="number" min="1000" step="1000" value="${item.targetVolume}" data-campaign-field="targetVolume"><b>units</b></div></label><label>Target MOQ<div><input type="number" min="1000" step="1000" value="${item.targetMoq}" data-campaign-field="targetMoq"><b>units</b></div></label><label>Current Planned Volume<div><input type="number" min="0" step="1000" value="${item.currentVolume}" data-campaign-field="currentVolume"><b>units</b></div></label><label>Current MOQ<div><input type="number" min="1000" step="1000" value="${item.currentMoq}" data-campaign-field="currentMoq"><b>units</b></div></label></div><footer><div><span>Volume Target Achievement</span><b data-product-achievement>${achievement.toFixed(1)}%</b></div><i><em data-product-achievement-bar style="width:${achievement}%"></em></i><small data-product-achievement-units>${fmt(Math.min(item.currentVolume,item.targetVolume))} / ${fmt(item.targetVolume)} units</small></footer></article>`}).join('')}</div><section class="campaign-optimize card"><div><span>OPTIMIZATION OBJECTIVE</span><h3>Maximize volume target achievement within manufacturing constraints</h3><p>Target volume remains a hard ceiling. Recommended production will never exceed marketing requirements.</p></div><label>MOQ treatment<select id="campaign-moq-mode"><option value="adjustable" ${state.moqMode==='adjustable'?'selected':''}>Optimization variable</option><option value="fixed" ${state.moqMode==='fixed'?'selected':''}>Fixed business constraint</option></select></label><button class="m2-secondary" id="create-launch">＋ New Campaign</button><button class="m2-primary campaign-optimize-button" id="apply-launches">Optimize Plan →</button></section><div class="campaign-method-grid"><article class="card"><span>01</span><div><b>Preserve the baseline</b><small>Start with the manufacturing team's current four-week plan.</small></div></article><article class="card"><span>02</span><div><b>Improve feasible output</b><small>Use PV, line, MOQ, and sequence changes to close target gaps.</small></div></article><article class="card"><span>03</span><div><b>Respect hard ceilings</b><small>Never produce above target volume or outside active constraints.</small></div></article></div>${campaignDraftDrawer()}${footer()}`}

function renderHome(){const m=state.plan.metrics;return `<section class="hero-run card"><span>⌘</span><div><h2>Integrated run strategy optimization</h2><p>Solve PV prioritization, MOQ, campaign sequencing and order cost together, rather than as separate calculators, to find the most economical way to run the plant.</p></div><div class="run-steps">${[['1','Assign PVs','Allocate to lines and versions'],['2','Set MOQs','Balance setup and inventory'],['3','Sequence campaigns','Minimise changeovers'],['4','Reconcile costs','Solve to consistency']].map((x,i)=>`<div class="run-step"><span>${x[0]}</span><p><b>${x[1]}</b><small>${x[2]}</small></p></div>${i<3?'<i>→</i>':''}`).join('')}</div></section><div class="kpi-grid five">${kpi('▦','Baseline order cost','$12.4M','Total cost over 4 weeks')}${kpi('▦','Recommended cost',`$${m.recommended_cost}M`,'Integrated optimized plan',`▼ ${metricDelta(m.current_cost,m.recommended_cost)}`)}${kpi('◷','Setup hours saved',`${m.setup_recommended} h`,'Recommended setup time',`▼ ${metricDelta(m.setup_current,m.setup_recommended)}`)}${kpi('⇄','Changeovers reduced',m.changeovers_recommended,'Recommended plan',`▼ ${metricDelta(m.changeovers_current,m.changeovers_recommended)}`)}${kpi('▥','Capacity utilization',`${m.utilisation_recommended}%`,'Recommended plan',`▲ ${m.utilisation_recommended-m.utilisation_current} pp`)}</div><div class="grid-3"><article class="card plan-card"><h3>▣ &nbsp; Current plan</h3><p>Current planner sequence and parameters.</p><div class="plan-sequence"><span>Foundation</span>→<span>Mascara</span>→<span>Lip Gloss</span></div><div class="plan-metrics"><div><b>5</b><small>Full cleans</small></div><div><b>420 h</b><small>Setup time</small></div><div><b>72%</b><small>Line occupancy</small></div></div></article><article class="card plan-card recommended"><h3 class="good">✦ &nbsp; Recommended plan</h3><p>Optimized sequence from the integrated model.</p><div class="plan-sequence"><span>Foundation</span>→<span>Lip Gloss</span>→<span>Mascara</span></div><div class="plan-metrics"><div><b>2</b><small>Full cleans <em class="good">▼ 60%</em></small></div><div><b>300 h</b><small>Setup time <em class="good">▼ 28.6%</em></small></div><div><b>87%</b><small>Line occupancy <em class="good">▲ 15 pp</em></small></div></div></article>${panel('☀ &nbsp; Key recommendations',`<div class="grid-2"><div><small>Preferred Production Version</small><strong class="good">PV #3</strong></div><div><small>Recommended MOQ</small><strong class="good">50,000 units</strong></div></div><h4>Expected business impact</h4><ul class="check-list"><li>Fewer changeovers and cleaning events</li><li>Higher line utilisation</li><li>Reduced planning complexity</li><li>Lower total production cost</li></ul>`,'','')}</div><div class="grid-3" style="margin-top:10px">${panel('Scenario comparison',`<table class="data-table"><thead><tr><th>Metric</th><th>Current plan</th><th>Recommended plan</th><th>Change</th></tr></thead><tbody><tr><td>Order cost</td><td>$12.4M</td><td>$${m.recommended_cost}M</td><td class="good">▼ ${metricDelta(m.current_cost,m.recommended_cost)}</td></tr><tr><td>Setup hours</td><td>142 h</td><td>${m.setup_recommended} h</td><td class="good">▼ ${metricDelta(m.setup_current,m.setup_recommended)}</td></tr><tr><td>Full cleans</td><td>18</td><td>10</td><td class="good">▼ 44.4%</td></tr><tr><td>Capacity utilization</td><td>72%</td><td>${m.utilisation_recommended}%</td><td class="good">▲ ${m.utilisation_recommended-72} pp</td></tr></tbody></table>`,'','Key metrics for current vs recommended plan.')}${panel('Order cost breakdown',barChart([['Current',4.82,4.82],['Recommended',3.87,3.87]],5),'','Cost components for current vs recommended plan.')}${panel('♢ &nbsp; Active constraints',`<ul class="check-list"><li>Cleaning validation</li><li>Line availability</li><li>Maintenance blackout</li><li>Due-date rules</li></ul><hr><h3>♙ &nbsp; Human-in-the-loop</h3><p>Recommendations are reviewed and approved by business users before release. Nothing is written back to SAP in the POC.</p>`)}</div>${footer()}`}

function renderStrategy(){const m=state.plan.metrics;return `<div class="subtabs">${['Overview','Key Metrics','Line Utilization','Product Mix','Changeovers','Inventory','Cost Breakdown'].map((x,i)=>`<button class="${i===0?'active':''}">${x}</button>`).join('')}<span style="flex:1"></span><button id="compare-scenarios">♙ &nbsp; Compare Scenarios</button></div><div class="kpi-grid">${splitKpi('▦','Total Order Cost','$12.4M',`$${m.recommended_cost}M`,`↓ ${metricDelta(m.current_cost,m.recommended_cost)} ($${(m.current_cost-m.recommended_cost).toFixed(1)}M)`)}${splitKpi('⇄','Total Changeovers',68,m.changeovers_recommended,`↓ ${metricDelta(68,m.changeovers_recommended)} (${68-m.changeovers_recommended} fewer)`)}${splitKpi('▥','Line Utilization','72%',`${m.utilisation_recommended}%`,`↑ ${m.utilisation_recommended-72} pp`)}${splitKpi('◇','Average Inventory','$3.2M',`$${m.inventory_recommended}M`,`↓ ${metricDelta(3.2,m.inventory_recommended)}`)}</div><div class="grid-2 wide-left">${panel('Cost Comparison ($M)',barChart([['Total',12.4,m.recommended_cost],['Production',6.2,5.8],['Setup',2.1,1.4],['Inventory',3.2,m.inventory_recommended],['Labour',.6,.6],['Other',.3,.4]],13),'','',`<div class="sequence-legend"><span><i style="background:#99a7b8"></i>Current Plan</span><span><i style="background:var(--orange)"></i>Recommended</span></div>`)}${panel('Changeovers by Line',`<div class="horizontal-bars">${state.plan.lines.map(l=>`<div><span>${l.line}</span><i><em style="width:${l.changeovers[0]/20*100}%"></em></i><b>${l.changeovers[0]}</b></div><div><span></span><i><em class="orange" style="width:${l.changeovers[1]/20*100}%"></em></i><b>${l.changeovers[1]}</b></div>`).join('')}</div>`)}${panel('☀ &nbsp; Key Takeaways',`<ul class="check-list"><li>${metricDelta(12.4,m.recommended_cost)} lower total order cost with the recommended plan.</li><li>${metricDelta(68,m.changeovers_recommended)} fewer changeovers, driven by improved sequencing.</li><li>Higher line utilization (+${m.utilisation_recommended-72} pp) across key filling lines.</li><li>Lower average inventory through optimized MOQs.</li></ul><hr><h4>What would you like to do next?</h4><ul class="action-list"><li data-jump="pv">Explore PV prioritisation</li><li data-jump="moq">Adjust MOQ parameters</li><li data-jump="campaign">Review campaign sequencing</li><li data-jump="scenario">Try a different scenario</li></ul>`)}</div>${panel('▤ &nbsp; Line Summary',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Line</th><th>Eligible SKUs</th><th>Production Hours<br><small>Current | Recommended</small></th><th>Utilization<br><small>Current | Recommended</small></th><th>Changeovers<br><small>Current | Recommended</small></th><th>Total Cost ($M)<br><small>Current | Recommended</small></th><th>Key Change</th></tr></thead><tbody>${planRows()}<tr class="total"><td>Total</td><td>278</td><td>1,500 &nbsp; | &nbsp; 1,650</td><td>72% &nbsp; | &nbsp; ${m.utilisation_recommended}%</td><td>68 &nbsp; | &nbsp; ${m.changeovers_recommended}</td><td>12.4 &nbsp; | &nbsp; ${m.recommended_cost}</td><td>—</td></tr></tbody></table></div>`,'', '', '')}${footer()}`}

function skuRows(){return state.plan.skus.map((s,i)=>`<tr data-sku="${s.sku}" class="${i===0?'recommended':''}"><td>${s.sku}</td><td>${s.product}</td><td><b>${s.pv}</b></td><td>${s.alternatives}</td><td>${s.line}</td><td>$${s.unit_cost}</td><td>${s.rate}</td><td>${s.yield}</td><td>$${s.total_cost}K</td><td><span class="tag ${s.delta<=0?'green':'red'}">${s.delta>0?'+':''}${s.delta}%</span></td><td>${s.rationale}</td></tr>`).join('')}
function renderPV(){return `<div class="kpi-grid">${kpi('⚙','Total Order Cost Impact','$1.6M','vs current PV assignment','↓ 12.9%')}${kpi('⌘','SKUs with PV Change','28 / 130','SKUs switched to a different PV','21.5%')}${splitKpi('▥','Average Unit Cost','$8.4','$7.3','↓ 13.1%')}${splitKpi('◷','Capacity Utilisation','72%','81%','(+9 pp)')}</div><div class="grid-2 wide-left">${panel('SKU PV Ranking',`<div class="table-toolbar"><input id="sku-search" placeholder="⌕  Search SKU or product..."><label>Product Category<select><option>All</option><option>Foundation</option><option>Mascara</option></select></label><label>Line<select><option>All</option><option>F04</option><option>F07</option></select></label><button class="m2-secondary">⇩ Export</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>SKU</th><th>Product</th><th>Recommended PV</th><th>Alternative PVs</th><th>Line</th><th>Unit Cost ($/unit)</th><th>Run Rate</th><th>Yield</th><th>Total Cost ($K)</th><th>Δ vs Current</th><th>Rationale</th></tr></thead><tbody id="sku-body">${skuRows()}</tbody></table></div>`,'','','') }<div class="stack">${panel('PV Cost Comparison — FND-001',barChart([['PV-1',32,18],['PV-2',25,15],['PV-3',16.5,12.5]],35),'','',`<div class="sequence-legend"><span><i style="background:#98a7b9"></i>Unit Cost</span><span><i style="background:var(--orange)"></i>Total Cost</span></div>`)}${panel('PV Performance — FND-001',`<table class="data-table"><thead><tr><th>Metric</th><th>PV-1</th><th>PV-2</th><th>PV-3<br>(Recommended)</th></tr></thead><tbody><tr><td>Run Rate</td><td>450</td><td>520</td><td class="good">600</td></tr><tr><td>Yield</td><td>95</td><td>96</td><td class="good">98</td></tr><tr><td>Setup Time</td><td>4.0</td><td>3.0</td><td class="good">2.0</td></tr><tr><td>Unit Cost</td><td>18.0</td><td>15.0</td><td class="good">12.5</td></tr></tbody></table>`)}</div></div><div class="grid-3" style="margin-top:10px">${panel('PV Switch Impact Summary',`<div class="grid-3"><div><small>Total SKUs Changed</small><strong>28</strong><p>21.5% of 130</p></div><div><small>Order Cost Reduction</small><strong>$1.6M</strong><p class="good">↓ 12.9%</p></div><div><small>Utilisation Increase</small><strong class="good">+9 pp</strong><p>72% → 81%</p></div></div>`)}${panel('Top PV Switches by Impact',`<table class="data-table"><tbody>${state.plan.skus.slice(0,5).map(s=>`<tr><td>${s.sku}</td><td>PV-1</td><td>${s.pv}</td><td class="good">${(s.delta/4).toFixed(1)}</td></tr>`).join('')}</tbody></table>`)}${panel('♙ &nbsp; Quick Actions',`<ul class="action-list"><li>View explainability for a SKU</li><li>Override PV for selected SKU</li><li data-jump="scenario">Run what-if scenario</li><li data-jump="strategy">Compare with current plan</li></ul>`)}</div>${footer()}`}

function renderMOQ(){return `<div class="grid-2 wide-left"><div><div class="kpi-grid" style="grid-template-columns:repeat(3,1fr)">${splitKpi('◇','Total Inventory ($M)','$3.2M','$2.6M','↓ 18.8% ($0.6M)')}${splitKpi('▦','Setup Cost ($M)','$2.1M','$1.4M','↓ 33.3% ($0.7M)')}${splitKpi('▧','Average MOQ (units)','20,000','34,000','↑ 70.0%')}</div>${panel('SKU Recommendations',`<div class="table-toolbar"><input id="moq-search" placeholder="⌕ Search SKU, product or line..."><label>Product Category<select><option>All</option></select></label><label>Line<select><option>All</option></select></label><button class="m2-secondary">⇩ Export</button></div><table class="data-table"><thead><tr><th>SKU</th><th>Product</th><th>Line</th><th>Current MOQ</th><th>Recommended MOQ</th><th>Change</th><th>Setup Cost ($K)</th><th>Holding Cost ($/unit/month)</th><th>Rationale</th></tr></thead><tbody id="moq-body">${state.plan.skus.map(s=>`<tr><td>${s.sku}</td><td>${s.product}</td><td>${s.line}</td><td>${fmt(s.moq[0])}</td><td>${fmt(s.moq[1])}</td><td class="good">${s.moq[1]===s.moq[0]?'0%':`+${Math.round((s.moq[1]/s.moq[0]-1)*100)}%`}</td><td>${usdK(s.setup)}</td><td>${usdUnit(s.holding)}</td><td>${s.rationale}</td></tr>`).join('')}</tbody></table>`,'','','')}</div><div class="stack">${panel('☀ &nbsp; Key Takeaways',`<ul class="check-list"><li>Higher MOQs reduce setup cost and total order cost.</li><li>Average inventory remains within target limits.</li><li>Some SKUs benefit from line-specific MOQ due to changeover profile.</li></ul>`)}${panel('Trade-off Curve – Lip Gloss (F05)',`<div class="tradeoff"><span class="optimal"><b>Optimal MOQ<br>35,000 units</b></span></div><p style="text-align:center">Lot Size (units)</p>`,'','',sequenceLegend())}${panel('☀ &nbsp; Insight',`<p>At 35,000 units, the total cost is 32% lower than the current MOQ of 10,000 units. Further increases give marginal benefits due to rising inventory cost.</p>`,'insight')}</div></div><div class="grid-2" style="margin-top:10px">${panel('MOQ Impact on Key Metrics',barChart([['Setup Cost',62,41],['Average Inventory',48,32],['Total Order Cost',124,108],['Line Utilization',72,81]],130))}${panel('Line Capacity and MOQ Feasibility',`<table class="data-table"><thead><tr><th>Line</th><th>Available Hours</th><th>Required Hours<br>(Current | Recommended)</th><th>Utilization</th><th>Feasible</th></tr></thead><tbody>${state.plan.lines.slice(0,5).map(l=>`<tr><td>${l.line}</td><td>720</td><td>${l.hours[0]+230} &nbsp; | &nbsp; ${l.hours[1]+260}</td><td>${l.utilisation[0]}% &nbsp; | &nbsp; ${l.utilisation[1]}%</td><td class="good">● Yes</td></tr>`).join('')}</tbody></table>`)}</div>${footer()}`}

function renderMOQPlan(){const m=state.plan.metrics,products=state.plan.campaign.products;return `<div class="grid-2 wide-left"><div><div class="kpi-grid" style="grid-template-columns:repeat(3,1fr)">${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,`${m.inventory_recommended>m.inventory_current?'↑ trade-off':'↓ improvement'}`)}${splitKpi('▦','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`↓ ${m.setup_current-m.setup_recommended} hrs`)}${splitKpi('▧','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`↑ ${m.achievement_gain} pp`)}</div>${panel('Product MOQ Recommendations',`<div class="table-toolbar"><input id="moq-search" placeholder="⌕ Search product or line..."><button class="m2-secondary">⇩ Export</button></div><table class="data-table"><thead><tr><th>SKU</th><th>Product</th><th>Line</th><th>Target Volume</th><th>Current MOQ</th><th>Target MOQ</th><th>Recommended MOQ</th><th>Recommended Volume</th><th>Rationale</th></tr></thead><tbody id="moq-body">${products.map(item=>`<tr><td>${item.sku}</td><td><b>${item.name}</b></td><td>${item.line}</td><td>${fmt(item.targetVolume)}</td><td>${fmt(item.currentMoq)}</td><td>${fmt(item.targetMoq)}</td><td class="good">${fmt(item.recommendedMoq)}</td><td>${fmt(item.recommendedVolume)}</td><td>${state.moqMode==='fixed'?'Marketing MOQ enforced as a fixed constraint':'Balances setup efficiency with the target-volume ceiling'}</td></tr>`).join('')}</tbody></table>`,'','','')}</div><div class="stack">${panel('MOQ Treatment',`<div class="moq-mode-card"><span>${state.moqMode==='fixed'?'FIXED CONSTRAINT':'OPTIMIZATION VARIABLE'}</span><strong>${state.moqMode==='fixed'?'Marketing target MOQ enforced':'MOQ optimized by product'}</strong><p>Target volume remains the hard ceiling in both modes.</p><button class="m2-secondary" data-jump="launch">Edit in Campaign Brief</button></div>`)}${panel('Trade-off Curve – New Hydrating Lotion (F04)',`<div class="tradeoff"><span class="optimal"><b>Recommended MOQ<br>${fmt(products[0].recommendedMoq)} units</b></span></div><p style="text-align:center">Lot Size (units)</p>`,'','',sequenceLegend())}${panel('Planning Insight',`<p>The recommended MOQ raises feasible volume from ${fmt(products[0].currentVolume)} to ${fmt(products[0].recommendedVolume)} units while staying below the ${fmt(products[0].targetVolume)}-unit marketing ceiling.</p>`,'insight')}</div></div><div class="grid-2" style="margin-top:10px">${panel('MOQ Impact on Active Products',`<div class="campaign-achievement-table compact"><header><span>Product</span><span>Current MOQ</span><span>Recommended</span><span>Current Volume</span><span>Recommended Volume</span></header>${products.map(item=>`<div><b>${item.name}</b><span>${fmt(item.currentMoq)}</span><span>${fmt(item.recommendedMoq)}</span><span>${fmt(item.currentVolume)}</span><span>${fmt(item.recommendedVolume)}</span></div>`).join('')}</div>`)}${panel('Line Capacity and MOQ Feasibility',`<table class="data-table"><thead><tr><th>Line</th><th>Product</th><th>Available Hours</th><th>Utilization<br>Current | Recommended</th><th>Feasible</th></tr></thead><tbody>${state.plan.lines.map((line,index)=>`<tr><td>${line.line}</td><td>${products[index].name}</td><td>720</td><td>${line.utilisation[0]}% | ${line.utilisation[1]}%</td><td class="good">● Yes</td></tr>`).join('')}</tbody></table>`)}</div>${footer()}`}
function renderCampaign(){const s=state.plan.sequences;return `<div class="kpi-grid">${splitKpi('⇄','Total Changeovers','68','49','↓ 27.9% (19 fewer)')}${splitKpi('◷','Total Setup Time','142 hrs','96 hrs','↓ 32.4% (46 hrs)')}${splitKpi('♨','Full Cleans','18','10','↓ 44.4% (8 fewer)')}${splitKpi('⌁','Average Run Length','12.4 hrs','18.6 hrs','↑ 50.0% (+6.2 hrs)')}</div><div class="grid-2 wide-left">${panel('Current Plan – Campaign Sequence',`${sequenceLegend()}${sequenceRows(s.current)}`)}${panel('Changeover Matrix (hrs)',`<table class="data-table"><thead><tr><th>From / To</th><th>Foundation</th><th>Mascara</th><th>Lip Gloss</th><th>Moisturizer</th><th>Cleanser</th></tr></thead><tbody>${['Foundation','Mascara','Lip Gloss','Moisturizer','Cleanser'].map((x,i)=>`<tr><td>${x}</td>${[0,1,2,3,4].map(j=>`<td style="background:${i===j?'#f7f8fa':'#fff0e8'}">${i===j?'–':(1+Math.abs(i-j)*.5).toFixed(1)}</td>`).join('')}</tr>`).join('')}</tbody></table>`)}${panel('Recommended Plan – Campaign Sequence',`${sequenceLegend()}${sequenceRows(s.recommended)}`)}${panel('Line Details – F04',`<table class="data-table"><thead><tr><th>#</th><th>Product</th><th>Start</th><th>End</th><th>Duration</th></tr></thead><tbody>${['Foundation','Changeover','Lip Gloss','Changeover','Mascara','Changeover','Foundation'].map((x,i)=>`<tr class="${x==='Changeover'?'total':''}"><td>${i+1}</td><td>${x}</td><td>Mon ${i+1} 08:00</td><td>Tue ${i+2} 12:00</td><td>${x==='Changeover'?'4.0':'36.0'}</td></tr>`).join('')}</tbody></table>`)}</div><div class="grid-2" style="margin-top:10px">${panel('☀ &nbsp; Insights',`<p>Line F04 moves from 3 changeovers to 2 changeovers (−33%), with longer, more stable campaigns.</p><p>Sequencing similar products (Foundation → Lip Gloss) reduces cleaning time and improves line utilisation.</p>`,'insight')}${panel('⚙ &nbsp; Quick Actions',`<div class="grid-3"><button class="m2-secondary">☷ Adjust Sequence</button><button class="m2-secondary">♢ Apply Rule</button><button class="m2-secondary">♙ Lock Line</button></div>`)}</div>${footer()}`}

function renderMOQWorkspace(){const m=state.plan.metrics,products=state.plan.campaign.products,selected=products.find(item=>item.id===state.selectedMOQProduct)||products[0],currentBatches=Math.max(1,Math.ceil(selected.currentVolume/selected.currentMoq)),recommendedBatches=Math.max(1,Math.ceil(selected.recommendedVolume/selected.recommendedMoq)),moqChange=Math.round((selected.recommendedMoq/selected.currentMoq-1)*100),volumeGain=selected.recommendedVolume-selected.currentVolume;return `<section class="moq-hero card"><div><span>LINE-LEVEL LOT-SIZE DECISIONS</span><h2>Balance setup efficiency with inventory exposure</h2><p>MOQ recommendations are optimized for the active campaign while every product target remains a hard ceiling.</p></div><section><small>MOQ treatment</small><strong>${state.moqMode==='fixed'?'Fixed business constraint':'Optimization variable'}</strong><button class="m2-secondary" data-jump="launch">Change treatment</button></section><section><small>Plan feasibility</small><strong class="good">3 of 3 products feasible</strong><span>0 target-volume breaches</span></section></section><div class="kpi-grid moq-kpis">${splitKpi('▧','Portfolio MOQ',`${fmt(Math.round(products.reduce((sum,item)=>sum+item.currentMoq,0)/products.length))}`,`${fmt(Math.round(products.reduce((sum,item)=>sum+item.recommendedMoq,0)/products.length))}`,state.moqMode==='fixed'?'Target values enforced':'Product-specific optimization')}${splitKpi('◷','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`↓ ${m.setup_current-m.setup_recommended} hrs`)}${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,m.inventory_recommended>m.inventory_current?'↑ Accepted service trade-off':'↓ Working-capital benefit')}${splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`↑ ${m.achievement_gain} pp`)}</div><div class="moq-product-selector">${products.map(item=>{const delta=Math.round((item.recommendedMoq/item.currentMoq-1)*100);return `<button class="card ${item.id===selected.id?'active':''}" data-moq-product="${item.id}"><i style="background:${item.color}"></i><span><small>${item.sku} · ${item.line}</small><b>${item.name}</b></span><em>${delta>=0?'+':''}${delta}% MOQ</em><strong>${fmt(item.recommendedMoq)}</strong></button>`}).join('')}</div><div class="grid-2 moq-decision-grid"><div class="stack">${panel('MOQ Recommendations',`<div class="table-toolbar"><input id="moq-search" placeholder="⌕ Search product, SKU, or line..."><button class="m2-secondary">⇩ Export</button></div><table class="data-table moq-table"><thead><tr><th>Product</th><th>Line / PV</th><th>Current MOQ</th><th>Target MOQ</th><th>Recommended</th><th>Change</th><th>Volume Achievement</th><th>Status</th></tr></thead><tbody id="moq-body">${products.map(item=>{const delta=Math.round((item.recommendedMoq/item.currentMoq-1)*100);return `<tr class="${item.id===selected.id?'selected':''}" data-moq-product="${item.id}"><td><b>${item.name}</b><small>${item.sku}</small></td><td>${item.line} / ${item.pv}</td><td>${fmt(item.currentMoq)}</td><td>${fmt(item.targetMoq)}</td><td><b>${fmt(item.recommendedMoq)}</b></td><td class="${delta>0?'warn':'good'}">${delta>=0?'+':''}${delta}%</td><td><div class="moq-inline-progress"><i><em style="width:${item.recommendedAchievement}%"></em></i><b>${item.recommendedAchievement.toFixed(1)}%</b></div></td><td><span class="tag green">Feasible</span></td></tr>`}).join('')}</tbody></table>`,'','Select a product to inspect the decision evidence.')}${panel('Capacity and Target Guardrails',`<div class="moq-guardrail-grid">${products.map((item,index)=>`<article><header><b>${item.line}</b><span>${item.name}</span><em class="good">Feasible</em></header><div><span>Line utilization</span><b>${state.plan.lines[index].utilisation[0]}% → ${state.plan.lines[index].utilisation[1]}%</b><i><em style="width:${state.plan.lines[index].utilisation[1]}%"></em></i></div><footer><span>Target ceiling</span><b>${fmt(item.recommendedVolume)} / ${fmt(item.targetVolume)}</b></footer></article>`).join('')}</div>`,'','Capacity, MOQ, and marketing ceilings are checked together.')}</div><div class="stack">${panel(`${selected.name} · MOQ Decision`, `<div class="moq-decision-card"><header><span>RECOMMENDED MOQ</span><strong>${fmt(selected.recommendedMoq)} <small>units</small></strong><em class="${moqChange>0?'warn':'good'}">${moqChange>=0?'+':''}${moqChange}% vs current</em></header><div class="moq-flow"><section><small>Current</small><b>${fmt(selected.currentMoq)}</b><span>${currentBatches} planned batches</span></section><i>→</i><section class="recommended"><small>Recommended</small><b>${fmt(selected.recommendedMoq)}</b><span>${recommendedBatches} planned batches</span></section></div><ul><li><span>Feasible volume gain</span><b class="good">+${fmt(volumeGain)} units</b></li><li><span>Target achievement</span><b>${selected.currentAchievement.toFixed(1)}% → ${selected.recommendedAchievement.toFixed(1)}%</b></li><li><span>Target ceiling</span><b class="good">No breach</b></li></ul></div>`,'','Decision summary for the selected product.')}${panel('Economic Trade-off',`<div class="moq-curve"><div class="moq-curve-axis y">Relative cost</div><svg viewBox="0 0 420 190" role="img" aria-label="MOQ economic trade-off curve"><path class="grid" d="M40 20V160M40 160H405M40 125H405M40 90H405M40 55H405"/><path class="setup" d="M48 32 C120 70 210 124 398 145"/><path class="inventory" d="M48 145 C155 141 275 105 398 38"/><path class="total" d="M48 58 C135 108 220 142 398 92"/><line x1="245" y1="25" x2="245" y2="160" class="marker"/><circle cx="245" cy="132" r="7"/><text x="257" y="123">Recommended ${fmt(selected.recommendedMoq)}</text></svg><div class="moq-curve-legend"><span><i></i>Total relevant cost</span><span><i></i>Setup cost</span><span><i></i>Inventory cost</span></div><div class="moq-curve-axis x">Lot size</div></div>`,'','The selected MOQ sits near the lowest combined-cost region.')}${panel('Why this recommendation?',`<div class="moq-reason-list"><article><span>01</span><p><b>Fewer setup cycles</b><small>${Math.max(0,currentBatches-recommendedBatches)} fewer planned batch starts release productive hours.</small></p></article><article><span>02</span><p><b>Improved target coverage</b><small>Adds ${fmt(volumeGain)} feasible units inside the four-week horizon.</small></p></article><article><span>03</span><p><b>Controlled inventory trade-off</b><small>Lot size remains within capacity, storage, and target-volume guardrails.</small></p></article></div><button class="m2-primary moq-review-button" data-jump="scenario">Review with Manufacturing →</button>`,'insight')}</div></div>${footer()}`}

function renderCampaignPlan(){const m=state.plan.metrics,s=state.plan.sequences,products=state.plan.campaign.products;return `<div class="kpi-grid">${splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`↑ ${m.achievement_gain} pp`)}${splitKpi('⇄','Total Changeovers',m.changeovers_current,m.changeovers_recommended,`↓ ${m.changeovers_current-m.changeovers_recommended} events`)}${splitKpi('◷','Total Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`↓ ${m.setup_current-m.setup_recommended} hrs`)}${splitKpi('▥','Achieved Volume',fmt(m.current_volume),fmt(m.recommended_volume),`+${fmt(m.recommended_volume-m.current_volume)} units`)}</div><div class="grid-2 wide-left">${panel('Current Plan – Campaign Sequence',`${sequenceLegend()}${sequenceRows(s.current)}`,'','Manufacturing team baseline for the same four-week period.')}${panel('Changeover Matrix (hrs)',`<table class="data-table"><thead><tr><th>From / To</th><th>Hydrating Lotion</th><th>Foundation</th><th>Mascara</th></tr></thead><tbody>${[['Hydrating Lotion','—','2.0','3.5'],['Foundation','2.0','—','4.0'],['Mascara','3.5','4.0','—']].map(row=>`<tr>${row.map((cell,index)=>`<td class="${index&&cell!=='—'?'matrix-value':''}">${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`)}${panel('Recommended Plan – Campaign Sequence',`${sequenceLegend()}${sequenceRows(s.recommended)}`,'','Dedicated product campaigns reduce transitions and protect feasible output.')}${panel('Recommended Product Plan',`<table class="data-table"><thead><tr><th>Product</th><th>Line / PV</th><th>Target</th><th>Recommended</th><th>MOQ</th><th>Achievement</th></tr></thead><tbody>${products.map(item=>`<tr><td><b>${item.name}</b></td><td>${item.line} / ${item.pv}</td><td>${fmt(item.targetVolume)}</td><td>${fmt(item.recommendedVolume)}</td><td>${fmt(item.recommendedMoq)}</td><td class="${item.recommendedAchievement<100?'warn':'good'}">${item.recommendedAchievement.toFixed(1)}%</td></tr>`).join('')}</tbody></table>`)}</div><div class="grid-2" style="margin-top:10px">${panel('Why the sequence improves output',`<div class="campaign-reasons"><article><span>01</span><p><b>F04 dedicated to Hydrating Lotion</b><small>Removes repeated Foundation ↔ Lotion transitions.</small></p></article><article><span>02</span><p><b>Foundation consolidated on F07</b><small>Uses the selected PV and releases shared F04 capacity.</small></p></article><article><span>03</span><p><b>Mascara campaigns lengthened</b><small>Target MOQ reduces setup frequency without exceeding demand.</small></p></article></div>`,'insight')}${panel('Operational trade-offs',`<div class="tradeoff-list"><li><span>Inventory holding</span><b class="warn">$${m.inventory_current}M → $${m.inventory_recommended}M</b></li><li><span>Setup time</span><b class="good">${m.setup_current} → ${m.setup_recommended} hrs</b></li><li><span>Volume achieved</span><b class="good">+${fmt(m.recommended_volume-m.current_volume)} units</b></li><li><span>Target ceiling breaches</span><b class="good">0</b></li></div>`)}</div>${footer()}`}
function renderCost(){const m=state.plan.metrics,products=state.plan.campaign.products,saving=Number((m.current_cost-m.recommended_cost).toFixed(2)),inventoryChange=Number((m.inventory_recommended-m.inventory_current).toFixed(2)),setupCurrent=Number((m.current_cost*.19).toFixed(2)),setupRecommended=Number((m.recommended_cost*.12).toFixed(2));return `<div class="kpi-grid">${splitKpi('▦','Production Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`${saving>=0?'↓':'↑'} $${Math.abs(saving).toFixed(2)}M`)}${splitKpi('⚙','Setup & Changeover',`$${setupCurrent}M`,`$${setupRecommended}M`,`↓ $${(setupCurrent-setupRecommended).toFixed(2)}M`)}${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,`${inventoryChange>0?'↑ trade-off':'↓ improvement'} $${Math.abs(inventoryChange).toFixed(2)}M`)}${splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`↑ ${m.achievement_gain} pp`)}</div><div class="grid-2">${panel('Cost Bridge ($M)',`<div class="waterfall"><div class="total" style="height:83%"><b>${m.current_cost}</b><span>Current Plan</span></div><div style="height:18%"><b>-${(setupCurrent-setupRecommended).toFixed(2)}</b><span>Setup</span></div><div class="${inventoryChange>0?'increase':''}" style="height:${Math.max(5,Math.abs(inventoryChange)*30)}%"><b>${inventoryChange>0?'+':''}${inventoryChange}</b><span>Inventory</span></div><div style="height:10%"><b>-${Math.max(0,(saving-(setupCurrent-setupRecommended)+inventoryChange)).toFixed(2)}</b><span>Conversion</span></div><div class="final" style="height:${Math.max(50,m.recommended_cost/m.current_cost*83)}%"><b>${m.recommended_cost}</b><span>Recommended</span></div></div>`,'','Cost movement for the active campaign only.')}${panel('Cost Breakdown – Current vs Recommended','<div class="cost-breakdown-anchor"></div>','','Same three products and four-week horizon.')}</div><div class="grid-2" style="margin-top:10px">${panel('Cost by Campaign Product',`<table class="data-table"><thead><tr><th>Product</th><th>Line / PV</th><th>Current Volume</th><th>Recommended Volume</th><th>Current Cost</th><th>Recommended Cost</th><th>Trade-off</th></tr></thead><tbody>${products.map((item,index)=>{const share=item.targetVolume/m.target_volume,current=Number((m.current_cost*share).toFixed(2)),recommended=Number((m.recommended_cost*share).toFixed(2));return `<tr><td><b>${item.name}</b><small>${item.sku}</small></td><td>${item.line} / ${item.pv}</td><td>${fmt(item.currentVolume)}</td><td>${fmt(item.recommendedVolume)}</td><td>$${current}M</td><td>$${recommended}M</td><td class="${recommended<=current?'good':'warn'}">${recommended<=current?'Efficiency gain':'Volume investment'}</td></tr>`}).join('')}</tbody></table>`)}${panel('Cost and Volume Trade-off',`<div class="campaign-achievement-table compact"><header><span>Metric</span><span>Current</span><span>Recommended</span><span>Change</span><span>Interpretation</span></header><div><b>Production cost</b><span>$${m.current_cost}M</span><span>$${m.recommended_cost}M</span><span class="good">-$${saving.toFixed(2)}M</span><span>Lower total cost</span></div><div><b>Average inventory</b><span>$${m.inventory_current}M</span><span>$${m.inventory_recommended}M</span><span class="${inventoryChange>0?'warn':'good'}">${inventoryChange>0?'+':''}$${inventoryChange}M</span><span>${inventoryChange>0?'Supports longer campaigns':'Working capital released'}</span></div><div><b>Achieved volume</b><span>${fmt(m.current_volume)}</span><span>${fmt(m.recommended_volume)}</span><span class="good">+${fmt(m.recommended_volume-m.current_volume)}</span><span>Closes marketing gap</span></div></div>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Key Insights','<div></div>','insight')}${panel('Cost Assumptions',`<div></div>`)}${panel('Quick Actions','<div></div>')}</div>${footer()}`}

function renderScenario(){const m=state.plan.metrics,scenario=state.plan.scenario||{name:'Lower MOQ - PV Mix 2',moq_adjustment:-25};return `<div class="kpi-grid five">${kpi('▦','Total Order Cost',`$${m.recommended_cost}M`,'vs Current Plan ($12.4M)',`▼ ${metricDelta(12.4,m.recommended_cost)}`)}${kpi('⚙','Total Changeovers',m.changeovers_recommended,'vs Current Plan (68)',`▼ ${metricDelta(68,m.changeovers_recommended)}`)}${kpi('◷','Total Setup Time',`${m.setup_recommended} hrs`,'vs Current Plan (142 hrs)',`▼ ${metricDelta(142,m.setup_recommended)}`)}${kpi('◇','Average Inventory',`$${m.inventory_recommended}M`,'vs Current Plan ($3.2M)',`▼ ${metricDelta(3.2,m.inventory_recommended)}`)}${kpi('▥','Line Utilisation',`${m.utilisation_recommended}%`,'vs Current Plan (72%)',`▲ ${m.utilisation_recommended-72} pp`)}</div><div class="grid-3" style="grid-template-columns:1fr 1.3fr .9fr">${panel('Scenario Controls',`<div class="controls"><label>Scenario Name<input id="scenario-name" type="text" value="${esc(scenario.name)}"></label><label>MOQ Adjustment<input id="moq-slider" type="range" min="-50" max="50" value="${scenario.moq_adjustment||-25}"><b id="moq-value">${scenario.moq_adjustment||-25}%</b></label><label>PV Priority<select id="pv-priority"><option>Use recommended (cost based)</option><option>Maximize throughput</option><option>Minimize inventory</option></select></label><label>Include Constraints</label><div class="checks"><label><input type="checkbox" checked> Cleaning validation rules</label><label><input type="checkbox" checked> Allergen / colour carryover</label><label><input id="strict-due" type="checkbox"> Due date priority (strict)</label></div><label>Planning Horizon<select><option>4 Weeks</option><option>8 Weeks</option></select></label></div><div class="grid-2"><button class="m2-primary" id="solve-scenario">▷ &nbsp; Re-solve Scenario</button><button class="m2-secondary" id="save-scenario">▯ &nbsp; Save Scenario</button></div>`,'','Adjust parameters and re-solve the integrated model.')}${panel('Scenario Comparison',`<table class="data-table"><thead><tr><th>Metric</th><th>Current</th><th>Recommended</th><th>Scenario</th><th>Δ vs Current</th></tr></thead><tbody><tr><td>Total Order Cost ($M)</td><td>12.4</td><td>10.8</td><td>${m.recommended_cost}</td><td class="good">-${metricDelta(12.4,m.recommended_cost)}</td></tr><tr><td>Changeovers</td><td>68</td><td>49</td><td>${m.changeovers_recommended}</td><td class="good">-${metricDelta(68,m.changeovers_recommended)}</td></tr><tr><td>Setup Time</td><td>142</td><td>96</td><td>${m.setup_recommended}</td><td class="good">-${metricDelta(142,m.setup_recommended)}</td></tr><tr><td>Average Inventory ($M)</td><td>3.2</td><td>2.6</td><td>${m.inventory_recommended}</td><td class="good">-${metricDelta(3.2,m.inventory_recommended)}</td></tr><tr><td>Capacity Utilisation</td><td>72%</td><td>81%</td><td>${m.utilisation_recommended}%</td><td class="good">+${m.utilisation_recommended-72} pp</td></tr><tr><td>Full Cleans</td><td>18</td><td>10</td><td>12</td><td class="good">-33.3%</td></tr></tbody></table>`,'','Key metrics across current, recommended and custom scenarios.') }<div class="stack">${panel('Cost Comparison ($M)',barChart([['Current',12.4,12.4],['Recommended',10.8,10.8],['Scenario',m.recommended_cost,m.recommended_cost]],14))}${panel('☀ &nbsp; Insight',`<p>This scenario changes total cost and utilization based on MOQ and due-date choices. Use Re-solve Scenario to update every dependent metric.</p>`,'insight')}</div></div><div class="grid-3" style="margin-top:10px">${panel('Sequence Impact – Line F04',`${sequenceLegend()}${sequenceRows(state.plan.sequences.recommended,['F04'])}`)}${panel('MOQ Impact – Selected SKUs',`<table class="data-table"><thead><tr><th>SKU</th><th>Current MOQ</th><th>Scenario MOQ</th><th>Change</th></tr></thead><tbody>${state.plan.skus.slice(0,4).map(s=>`<tr><td>${s.sku}</td><td>${fmt(s.moq[0])}</td><td>${fmt(Math.round(s.moq[1]*(1+(scenario.moq_adjustment||-25)/100)))}</td><td class="good">${scenario.moq_adjustment||-25}%</td></tr>`).join('')}</tbody></table>`)}${panel('⚙ &nbsp; Quick Scenarios',`<ul class="action-list"><li data-quick="25">Increase MOQ by 25%</li><li data-quick="0">Prioritise PV-1 for all SKUs</li><li data-quick="-10">Relax cleaning rules</li><li data-quick="-25">Lower MOQ by 25%</li><li data-quick="40">High demand scenario</li></ul>`)}</div>${footer()}`}

function renderManufacturingReview(){const m=state.plan.metrics,o=state.reviewOptions,products=state.plan.campaign.products;return `<div class="review-banner card"><div><span>MANUFACTURING TEAM REVIEW</span><h2>Validate the proposed plan before approval</h2><p>Adjust supported operating values only, then resolve to load another precomputed feasible solution.</p></div><div><b>${state.plan.launch_context?.label||'Balanced recommendation'}</b><small>Solution ${state.solutionVariant+1} · 3 campaign products</small></div></div><div class="kpi-grid five">${kpi('◎','Target Achievement',`${m.recommended_achievement}%`,`Current plan ${m.current_achievement}%`,`▲ ${m.achievement_gain} pp`)}${kpi('▦','Production Cost',`$${m.recommended_cost}M`,`Current plan $${m.current_cost}M`,`▼ ${metricDelta(m.current_cost,m.recommended_cost)}`)}${kpi('⚙','Changeovers',m.changeovers_recommended,`Current plan ${m.changeovers_current}`,`▼ ${m.changeovers_current-m.changeovers_recommended} events`)}${kpi('◇','Average Inventory',`$${m.inventory_recommended}M`,`Current plan $${m.inventory_current}M`)}${kpi('▥','Line Utilisation',`${m.utilisation_recommended}%`,'Feasible campaign plan',`▲ ${m.utilisation_recommended-m.utilisation_current} pp`)}</div><div class="grid-2 wide-left"><div class="stack">${panel('Active Campaign Products',`<div class="portfolio-list">${products.map(item=>`<div><i style="background:${item.color}"></i><span><b>${item.name}</b><small>${item.sku} · ${fmt(item.recommendedVolume)} of ${fmt(item.targetVolume)} units</small></span><em>${item.line} · ${item.pv}</em></div>`).join('')}</div>`,'','Defined in Campaign Brief')}${panel('Supported Manufacturing Adjustments',`<div class="review-controls"><label><span>MOQ adjustment<small>Across the three campaign products</small></span><input id="review-moq" type="range" min="-30" max="40" step="5" value="${o.moq_adjustment}"><b id="review-moq-value">${o.moq_adjustment>0?'+':''}${o.moq_adjustment}%</b></label><label><span>Maximum line utilisation<small>Capacity guardrail</small></span><select id="review-capacity"><option value="75" ${o.capacity===75?'selected':''}>75%</option><option value="85" ${o.capacity===85?'selected':''}>85%</option><option value="90" ${o.capacity===90?'selected':''}>90%</option></select></label><label><span>Line availability<small>Existing line constraint</small></span><select id="review-line"><option ${o.line_constraint==='Standard availability'?'selected':''}>Standard availability</option><option ${o.line_constraint==='F04 reduced capacity'?'selected':''}>F04 reduced capacity</option><option ${o.line_constraint==='F07 unavailable'?'selected':''}>F07 unavailable</option></select></label><label><span>Campaign freeze window<small>Existing scheduling rule</small></span><select id="review-freeze"><option value="0" ${o.freeze_days===0?'selected':''}>No freeze</option><option value="3" ${o.freeze_days===3?'selected':''}>3 days</option><option value="5" ${o.freeze_days===5?'selected':''}>5 days</option></select></label><label><span>Maximum campaign length<small>Existing process rule</small></span><select id="review-campaign"><option value="96" ${o.max_campaign===96?'selected':''}>96 hours</option><option value="120" ${o.max_campaign===120?'selected':''}>120 hours</option><option value="144" ${o.max_campaign===144?'selected':''}>144 hours</option></select></label><label class="review-check"><span>Strict due-date priority<small>Existing scheduling constraint</small></span><input id="review-strict" type="checkbox" ${o.strict_due_dates?'checked':''}></label></div><div class="resolve-bar"><p><b>No new rule types can be created.</b><br>Resolve Plan recalculates the three-product campaign using these supported values.</p><button class="m2-primary" id="resolve-review">↻ &nbsp; Resolve Plan / Re-optimize</button></div>`,'','Reviewable constraints and planning assumptions')}</div><div class="stack">${panel('Proposed Plan Snapshot',`<table class="data-table"><tbody><tr><td>Volume achievement</td><td><b>${m.recommended_achievement}%</b></td></tr><tr><td>MOQ treatment</td><td><b>${state.moqMode==='fixed'?'Fixed constraint':'Optimization variable'}</b></td></tr><tr><td>Production lines</td><td><b>F04, F07, F02</b></td></tr><tr><td>Active constraints</td><td><b>${state.plan.constraints.filter(c=>c.active).length}</b></td></tr><tr><td>Plan status</td><td class="good"><b>Feasible · no target breaches</b></td></tr></tbody></table>`)}${panel('Sequence Preview',`${sequenceLegend()}${sequenceRows(state.plan.sequences.recommended,['F04','F07','F02'])}`)}${panel('Changes Pending Review',`<ul class="check-list"><li>PV assignments aligned to all three campaign products</li><li>MOQ values checked against capacity and target ceilings</li><li>Campaigns sequenced against active rules</li><li>Cost, output and utilization refreshed together</li></ul>`,'insight')}</div></div>${footer()}`}

const CONSTRAINT_VALUES={
  'R-004':['Last 1 day','Last 3 days','Last 5 days'],
  'R-005':['Priority = 1','Priority ≤ 2','All confirmed orders'],
  'R-007':['96 hrs','120 hrs','144 hrs'],
  'R-008':['8 hrs','12 hrs','24 hrs'],
  'R-009':['Standard calendar','F04 reduced capacity','F07 unavailable'],
  'R-010':['2,500 units','5,000 units','10,000 units'],
  'R-011':['60 days','90 days','120 days']
};
function constraintRows(){return state.plan.constraints.filter(c=>(!state.constraintSearch||`${c.name} ${c.type}`.toLowerCase().includes(state.constraintSearch))&&(state.constraintType==='All'||c.type===state.constraintType)).map(c=>`<tr><td>${c.id}</td><td>${c.name}</td><td>${c.type}</td><td>${c.description}</td><td>${CONSTRAINT_VALUES[c.id]?`<select class="constraint-value" data-constraint-value="${c.id}">${CONSTRAINT_VALUES[c.id].map(value=>`<option ${value===c.value?'selected':''}>${value}</option>`).join('')}</select>`:c.value}</td><td><button class="toggle ${c.active?'on':''}" data-constraint="${c.id}"></button></td><td><span class="impact-${c.impact.toLowerCase()}">${c.impact}</span></td><td>ⓘ</td></tr>`).join('')}
function renderConstraints(){const active=state.plan.constraints.filter(c=>c.active).length,m=state.plan.metrics;return `<div class="kpi-grid">${kpi('♢','Active Constraints',`${active} of 12`,'Existing rules included in solve')}${kpi('△','Constraint Violations','0','In recommended plan','','good')}${kpi('◷','Recommended Setup Time',`${m.setup_recommended} hrs`,'Reflects active constraints')}${kpi('♙','Recommended Cost',`$${m.recommended_cost}M`,'Active campaign plan')}</div><div class="grid-2 wide-left">${panel('Constraint Rules',`<div class="constraint-notice">Adjust existing constraint status and supported values. New constraint types cannot be created.</div><div class="table-toolbar"><input id="constraint-search" value="${esc(state.constraintSearch)}" placeholder="⌕ Search rules..."><label>Rule Type<select id="constraint-type"><option>All</option>${[...new Set(state.plan.constraints.map(c=>c.type))].map(x=>`<option ${x===state.constraintType?'selected':''}>${x}</option>`).join('')}</select></label><label>Status<select><option>All</option><option>Active</option></select></label><button class="m2-primary" id="resolve-constraints">↻ Resolve Plan</button></div><table class="data-table"><thead><tr><th>ID</th><th>Rule Name</th><th>Type</th><th>Description</th><th>Parameter / Value</th><th>Status</th><th>Impact</th><th>Info</th></tr></thead><tbody id="constraint-body">${constraintRows()}</tbody></table>`,'','Only configured manufacturing rules can be adjusted.') }<div class="stack">${panel('Impact on Sequence — Line F04',`${sequenceLegend()}${sequenceRows(state.plan.sequences.current,['F04'])}${sequenceRows(state.plan.sequences.recommended,['F04'])}`)}${panel('Constraint Impact Summary',`<table class="data-table"><thead><tr><th>Metric</th><th>Current</th><th>Resolved</th><th>Impact</th></tr></thead><tbody><tr><td>Volume achievement</td><td>${m.current_achievement}%</td><td>${m.recommended_achievement}%</td><td class="good">+${m.achievement_gain} pp</td></tr><tr><td>Total Order Cost ($M)</td><td>${m.current_cost}</td><td>${m.recommended_cost}</td><td class="good">-${metricDelta(m.current_cost,m.recommended_cost)}</td></tr><tr><td>Changeovers</td><td>${m.changeovers_current}</td><td>${m.changeovers_recommended}</td><td class="good">-${m.changeovers_current-m.changeovers_recommended}</td></tr><tr><td>Setup Time</td><td>${m.setup_current}</td><td>${m.setup_recommended}</td><td class="good">-${m.setup_current-m.setup_recommended} hrs</td></tr><tr><td>Line Utilisation</td><td>${m.utilisation_current}%</td><td>${m.utilisation_recommended}%</td><td class="good">+${m.utilisation_recommended-m.utilisation_current} pp</td></tr><tr><td>Violations</td><td>5</td><td>0</td><td class="good">-100%</td></tr></tbody></table>`)}</div></div><div class="grid-2" style="margin-top:10px">${panel('☀ &nbsp; Key Takeaways',`<ul class="check-list"><li>Existing rules can be switched on/off and supported parameter values adjusted.</li><li>The recommended plan respects every active constraint.</li><li>Resolve Plan updates the active campaign across all Module 2 views.</li></ul>`,'insight')}${panel('⚙ &nbsp; Next Steps',`<ol><li>Review active constraint values</li><li>Resolve the plan and compare changes</li><li>Validate results in Manufacturing Review</li><li>Submit the final plan for approval</li></ol>`)}</div>${footer()}`}

function renderExplain(){return `<div class="view-tabs">${['Transition Reasoning','MOQ Reasoning','PV Reasoning','Cost Breakdown','Rule Impact'].map((x,i)=>`<button class="${i===0?'active':''}">${x}</button>`).join('')}</div>${panel('⇄ &nbsp; Transition: Foundation → Lip Gloss (Line F04)',`<div class="grid-2 wide-left"><p>This transition was chosen in the recommended sequence because it avoids a full clean, has lower setup time and cost, and satisfies all active rules.</p><div class="score-card"><span>✓</span><div><b class="good">Recommended</b><small>Position 2 → 3 in sequence</small></div></div></div>`)}<div class="kpi-grid five" style="margin-top:10px">${kpi('◷','Setup Time','2.0 hrs','vs Mascara → Lip Gloss','↓ 4.0 hrs')}${kpi('▦','Setup Cost','$0.8K','vs Mascara → Lip Gloss','↓ 1.6K')}${kpi('△','Cleaning Requirement','No full clean','Only standard line clearance')}${kpi('▤','Rules Applied','2 rules','Colour family compatible · No allergen conflict')}${kpi('▥','Impact on Plan','$1.1K saved','on this transition','','good')}</div><div class="grid-2 wide-left">${panel('Transition Comparison',`<table class="data-table"><thead><tr><th>From → To</th><th>Setup Time</th><th>Cleaning</th><th>Setup Cost ($K)</th><th>Rule Status</th><th>Selected</th></tr></thead><tbody><tr class="recommended"><td><b>Foundation → Lip Gloss</b></td><td>2.0</td><td>Line clearance</td><td>0.8</td><td class="good">● Allowed</td><td class="good">●</td></tr>${['Mascara','Moisturizer','Sunscreen'].map((x,i)=>`<tr><td>${x} → Lip Gloss</td><td>${6-i*1.5}</td><td>Full clean</td><td>${2.4-i*.4}</td><td class="bad">⊗ Allowed</td><td>○</td></tr>`).join('')}</tbody></table>`,'','Why this transition and not an alternative?')}${panel('Sequence Context — Line F04',`${sequenceLegend()}${sequenceRows(state.plan.sequences.current,['F04'])}${sequenceRows(state.plan.sequences.recommended,['F04'])}`)}</div><div class="grid-3" style="margin-top:10px">${panel('Rule Breakdown',`<table class="data-table"><thead><tr><th>Rule</th><th>Result</th></tr></thead><tbody>${['Cleaning validation (GMP)','Allergen carryover','Colour family changeover','Campaign freeze period','Shared equipment conflict','Line availability','Maximum campaign length'].map((x,i)=>`<tr><td>${x}</td><td class="good">● ${i===0?'No full clean required':i===2?'Same family (compatible)':'No conflict'}</td></tr>`).join('')}</tbody></table>`)}${panel('Cost Impact Detail',barChart([['Mascara → Lip',2.4,1.6],['Foundation → Lip',.8,.6]],3))}<div class="stack">${panel('☀ &nbsp; Key Takeaways',`<ul class="check-list"><li>Foundation → Lip Gloss avoids a full clean and reduces setup time by 67%.</li><li>All active constraints are satisfied.</li><li>This transition saves ~$1.1K with no negative downstream impact.</li></ul>`,'insight')}${panel('⚙ &nbsp; Next Actions',`<ul class="action-list"><li data-jump="moq">View MOQ impact for Lip Gloss</li><li data-jump="pv">See PV options for Lip Gloss</li><li data-jump="campaign">Try an alternative sequence</li><li data-jump="constraints">Adjust cleaning rules</li></ul>`)}</div></div>${footer()}`}

function renderReview(){const m=state.plan.metrics;return `<div class="kpi-grid">${kpi('▤','Plan Status',state.approved?'Approved':'Ready for Approval','All checks passed','','good')}${kpi('▥','Total Cost ($M)',`$${m.recommended_cost}M`,'vs Current Plan ($12.4M)',`↓ ${metricDelta(12.4,m.recommended_cost)}`)}${kpi('◷','Total Setup Time',`${m.setup_recommended} hrs`,'vs Current Plan (142 hrs)',`↓ ${metricDelta(142,m.setup_recommended)}`)}${kpi('▥','Total Production (units)','5.8 M','Meets demand plan','→ No change')}</div><div class="grid-2 wide-left">${panel('Plan Comparison',`<table class="data-table"><thead><tr><th>Metric</th><th>Current Plan</th><th>Recommended</th><th>Alternative 1</th><th>Alternative 2</th></tr></thead><tbody>${[['Total Cost ($M)',12.4,m.recommended_cost,11.6,11.1],['Setup Time',142,m.setup_recommended,110,105],['Changeovers',68,m.changeovers_recommended,56,52],['Average Inventory ($M)',3.2,m.inventory_recommended,2.9,2.8],['Line Utilisation','72%','81%','77%','79%'],['Total Production','5.8 M','5.8 M','5.8 M','5.8 M'],['Constraint Violations',5,0,1,0]].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td class="good">${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td></tr>`).join('')}</tbody></table>`,'','Compare key metrics across current plan, recommended plan and selected alternatives.')}${panel('Cost vs Service Trade-off',`<div class="bubble-chart"><span class="bubble recommended" style="width:38px;height:38px;left:35%;top:18%">Rec.</span><span class="bubble" style="width:28px;height:28px;left:58%;top:27%">A1</span><span class="bubble" style="width:27px;height:27px;left:45%;top:38%">A2</span><span class="bubble" style="width:34px;height:34px;right:12%;top:57%;background:#2478df">Current</span></div>`,'','Recommended plan provides the best balance of cost and service level.')}</div><div class="grid-3" style="margin-top:10px">${panel('Checks & Validations',`<ul class="check-list"><li>Demand fulfilment <b class="good" style="float:right">Pass</b></li><li>Capacity constraints <b class="good" style="float:right">Pass</b></li><li>MOQ requirements <b class="good" style="float:right">Pass</b></li><li>Cleaning & allergen rules <b class="good" style="float:right">Pass</b></li><li>Regulatory constraints <b class="good" style="float:right">Pass</b></li><li>Plan feasibility <b class="good" style="float:right">Pass</b></li></ul>`)}${panel('Key Changes vs Current Plan',`<table class="data-table"><tbody><tr><td>49</td><td class="good">↓ 27.9%</td><td>Fewer changeovers</td></tr><tr><td>-46 hrs</td><td class="good">↓ 32.4%</td><td>Lower setup time</td></tr><tr><td>+9 pp</td><td class="good">↑ 72%→81%</td><td>Higher utilisation</td></tr><tr><td>-$1.6M</td><td class="good">↓ 12.9%</td><td>Total cost reduction</td></tr></tbody></table>`)}${panel('Approval Workflow',`<div class="approval-flow"><div class="approval-step active"><span>1</span><div><b>Review Plan</b><small>Validate metrics and assumptions</small></div><em>In Progress</em></div><div class="approval-step"><span>2</span><div><b>Business Approval</b><small>Operations, Supply Chain, Finance</small></div><em>Pending</em></div><div class="approval-step"><span>3</span><div><b>Final Sign-off</b><small>Authorise plan for execution</small></div><em>Pending</em></div></div>`)}</div><article class="card approval-actions" style="margin-top:10px"><textarea id="approval-comments" placeholder="Add comments or notes for approvers..."></textarea><button class="m2-secondary">⇩ Export Plan</button><button class="m2-secondary">▤ View Plan Details</button><button class="m2-primary" id="approve-plan">✓ &nbsp; ${state.approved?'Plan Approved':'Submit for Approval'}</button></article>${footer()}`}

function renderModel(){return `<div class="view-tabs" id="model-tabs">${['Data Overview','Data Ingestion','Model Configuration','Solver Settings','Audit & Logs'].map((x,i)=>`<button class="${i===0?'active':''}" data-model-tab="${i}">${x}</button>`).join('')}</div><div id="model-panel"><div class="kpi-grid five">${kpi('▦','Total SKUs','427','Across 4 categories')}${kpi('▥','Filling Lines','8','Including compounding')}${kpi('▤','Historical Records','24.3K','Production orders')}${kpi('▣','Planning Horizon','4 Weeks','26-Sep-2026 to 23-Oct-2026')}${kpi('✓','Data Quality Score','98.2%','All critical data available')}</div><div class="grid-3">${panel('SKU Distribution by Product Category',`<div class="donut-row"><div class="donut" data-label="427\A SKUs"></div><ul class="legend"><li><i style="background:#3888ed"></i>Foundation 162 (38%)</li><li><i></i>Mascara 98 (23%)</li><li><i style="background:#f8b339"></i>Lip Gloss 87 (20%)</li><li><i style="background:#9aa8bc"></i>Moisturizer 80 (19%)</li></ul></div>`)}${panel('Eligible Lines per SKU',barChart([['1',68,68],['2',142,142],['3',126,126],['4',67,67],['5+',24,24]],150))}${panel('Historical Order Volume',`<div class="line-chart"><i class="line" style="top:42%;transform:rotate(-2deg)"></i></div><div class="line-chart-labels"><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span></div>`)}</div><div class="grid-2 wide-left" style="margin-top:10px">${panel('Recent Data Assets',`<table class="data-table"><thead><tr><th>File Name</th><th>Type</th><th>Records</th><th>Last Updated</th><th>Status</th></tr></thead><tbody>${[['SKU_Master_v2.xlsx','Master Data','427'],['Line_Capacity.xlsx','Line Data','8'],['Changeover_Matrix.xlsx','Setup Data','1,024'],['Historical_Orders.csv','Production Data','24,312'],['BOM_Routes.xlsx','Routing Data','427']].map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td><td>20-Sep-2026</td><td class="good">● Loaded</td></tr>`).join('')}</tbody></table>`)}${panel('Data Quality Checks',`<ul class="check-list"><li>Missing values <b class="good" style="float:right">0 critical issues</b></li><li>Data type validation <b class="good" style="float:right">Passed</b></li><li>SKU-line compatibility <b class="good" style="float:right">Passed</b></li><li>Changeover matrix completeness <b class="good" style="float:right">Passed</b></li><li>Capacity and calendar data <b class="good" style="float:right">Passed</b></li><li>Duplicate records <b class="good" style="float:right">0 found</b></li></ul>`)}</div><div class="grid-2 wide-left" style="margin-top:10px">${panel('▥ &nbsp; Model Inputs Summary',`<div class="grid-2"><ul class="action-list"><li>Demand forecast — 4 weeks · 427 SKUs</li><li>Line Capacities — 8 lines + compounding</li><li>Changeover matrix — 1,024 combinations</li></ul><ul class="action-list"><li>MOQ rules — Line-level configuration</li><li>BOM & routing — 427 SKUs</li><li>Calendar & constraints — Maintenance, holidays</li></ul></div>`)}${panel('Add / Update Data',`<div style="padding:22px;border:1px dashed #9ebbe0;text-align:center"><strong>☁ &nbsp; Drag and drop files here, or</strong><br><button class="m2-secondary" id="browse-data" style="margin-top:10px">Browse Files</button><p>Supported formats: Excel (.xlsx), CSV (.csv)</p></div>`)}</div></div>${footer()}`}

function renderSettings(){return `<div class="grid-2"><div class="stack">${panel('Optimization Defaults',`<div class="controls"><label>Default horizon<select><option>4 Weeks</option><option>8 Weeks</option></select></label><label>Primary objective<select><option>Minimize total order cost</option><option>Maximize service level</option></select></label><label>Solver tolerance<select><option>Balanced (1%)</option><option>Precise (0.1%)</option></select></label><label>Maximum solve time<select><option>90 seconds</option><option>5 minutes</option></select></label></div><button class="m2-primary" id="save-settings">Save Settings</button>`)}${panel('Cost Parameters',`<table class="data-table"><tbody><tr><td>Labour rate</td><td>$1,200 / hour</td></tr><tr><td>Standard clean</td><td>$50,000</td></tr><tr><td>Full clean</td><td>$120,000</td></tr><tr><td>Inventory holding</td><td>18% / annum</td></tr></tbody></table>`)}</div><div class="stack">${panel('Approval Preferences',`<div class="controls"><label>Require Operations approval<input type="checkbox" checked></label><label>Require Finance approval<input type="checkbox" checked></label><label>Allow planner override<input type="checkbox" checked></label><label>Auto-export approved plan<input type="checkbox"></label></div>`)}${panel('Environment',`<div class="score-card"><span>✓</span><div><b class="good">Synthetic POC Ready</b><small>Data and solver services are available.</small></div></div><table class="data-table" style="margin-top:12px"><tbody><tr><td>Model version</td><td>v1.2.0</td></tr><tr><td>Dataset</td><td>Synthetic manufacturing plan</td></tr><tr><td>Site</td><td>ELC - Site 1</td></tr><tr><td>Write-back</td><td>Disabled</td></tr></tbody></table>`)}</div></div>${footer()}`}

function strategyTabBar(){const tabs=[['overview','Overview'],['metrics','Key Metrics'],['utilization','Line Utilization'],['mix','Product Mix'],['changeovers','Changeovers'],['inventory','Inventory'],['costs','Cost Breakdown']];return `<div class="subtabs tab-strip" role="tablist">${tabs.map(([key,label])=>`<button role="tab" aria-selected="${state.strategyTab===key}" data-strategy-tab="${key}" class="${state.strategyTab===key?'active':''}">${label}</button>`).join('')}<span style="flex:1"></span><button id="compare-scenarios">♙ &nbsp; Compare Scenarios</button></div>`}
function strategyMetrics(){const m=state.plan.metrics;return `<div class="tab-content-enter"><div class="kpi-grid five">${kpi('▦','Total Order Cost',`$${m.recommended_cost}M`,'$12.4M baseline',`▼ ${metricDelta(12.4,m.recommended_cost)}`)}${kpi('⇄','Changeovers',m.changeovers_recommended,'68 current',`▼ ${68-m.changeovers_recommended} events`)}${kpi('◷','Setup Time',`${m.setup_recommended} hrs`,'142 hrs current',`▼ ${142-m.setup_recommended} hrs`)}${kpi('◇','Average Inventory',`$${m.inventory_recommended}M`,'$3.2M current',`▼ ${metricDelta(3.2,m.inventory_recommended)}`)}${kpi('▥','Service Level','99.1%','98.2% current','▲ 0.9 pp')}</div><div class="grid-2">${panel('Plan KPI Comparison',barChart([['Cost',100,87],['Setup',100,68],['Inventory',100,81],['Changeovers',100,72],['Utilization',72,m.utilisation_recommended]],105),'','Indexed current plan = 100')}${panel('Optimization Value Bridge',`<table class="data-table"><thead><tr><th>Value Lever</th><th>Current</th><th>Recommended</th><th>Impact</th><th>Confidence</th></tr></thead><tbody><tr><td>Production version mix</td><td>Legacy assignment</td><td>28 SKU changes</td><td class="good">$0.52M</td><td><span class="tag green">High</span></td></tr><tr><td>Line-level MOQ</td><td>20K avg.</td><td>34K avg.</td><td class="good">$0.44M</td><td><span class="tag green">High</span></td></tr><tr><td>Campaign sequence</td><td>68 changes</td><td>${m.changeovers_recommended} changes</td><td class="good">$0.38M</td><td><span class="tag green">High</span></td></tr><tr><td>Inventory balance</td><td>$3.2M</td><td>$${m.inventory_recommended}M</td><td class="good">$0.26M</td><td><span class="tag orange">Medium</span></td></tr></tbody></table>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Financial Impact',`<strong class="tab-big-number">$${(12.4-m.recommended_cost).toFixed(1)}M</strong><p>Estimated order-cost reduction over the four-week horizon.</p><div class="progress"><i style="width:78%"></i></div>`)}${panel('Operational Impact',`<strong class="tab-big-number">${142-m.setup_recommended} hrs</strong><p>Setup time released back into productive capacity.</p><div class="progress"><i style="width:68%"></i></div>`)}${panel('Plan Robustness',`<strong class="tab-big-number">94%</strong><p>Scenario stability across demand and capacity variations.</p><div class="progress"><i style="width:94%"></i></div>`)}</div></div>`}
function strategyUtilization(){const lines=state.plan.lines;return `<div class="tab-content-enter"><div class="kpi-grid">${kpi('▥','Plant Utilisation','81%','Recommended plan','▲ 9 pp')}${kpi('⌁','Bottleneck Line','F04','86% recommended utilization')}${kpi('◷','Available Capacity','390 hrs','Across the four-week horizon')}${kpi('✓','Capacity Violations','0','All lines remain feasible')}</div><div class="grid-2 wide-left">${panel('Utilisation by Filling Line',`<div class="utilization-chart">${lines.map(l=>`<div><b>${l.line}</b><span><i style="width:${l.utilisation[0]}%"></i><em>${l.utilisation[0]}%</em></span><span><i class="recommended" style="width:${l.utilisation[1]}%"></i><em>${l.utilisation[1]}%</em></span></div>`).join('')}</div>`,'','Current versus recommended capacity load',`<div class="sequence-legend"><span><i style="background:#98a7b9"></i>Current</span><span><i style="background:var(--orange)"></i>Recommended</span></div>`)}${panel('Capacity Health',`<ul class="capacity-list">${lines.map(l=>`<li><span><b>${l.line}</b><small>${720-l.hours[1]} hrs remaining</small></span><em class="${l.utilisation[1]>=85?'watch':'healthy'}">${l.utilisation[1]>=85?'Watch':'Healthy'}</em></li>`).join('')}</ul>`)}</div>${panel('Line Capacity Detail',`<table class="data-table"><thead><tr><th>Line</th><th>Available Hours</th><th>Current Hours</th><th>Recommended Hours</th><th>Current Util.</th><th>Recommended Util.</th><th>Remaining Capacity</th><th>Status</th></tr></thead><tbody>${lines.map(l=>`<tr><td><b>${l.line}</b></td><td>720</td><td>${l.hours[0]}</td><td>${l.hours[1]}</td><td>${l.utilisation[0]}%</td><td><b class="good">${l.utilisation[1]}%</b></td><td>${720-l.hours[1]} hrs</td><td><span class="tag ${l.utilisation[1]>=85?'orange':'green'}">${l.utilisation[1]>=85?'Monitor':'Feasible'}</span></td></tr>`).join('')}</tbody></table>`,'','Recommended loads respect planned maintenance and shift calendars.')}</div>`}
function strategyMix(){return `<div class="tab-content-enter"><div class="kpi-grid">${kpi('◇','Planned SKUs','130','Across 4 product categories')}${kpi('▦','Total Production','5.8 M units','Demand fully covered')}${kpi('▥','Largest Category','Foundation','38% of planned volume')}${kpi('⌘','PV Changes','28 SKUs','21.5% of active portfolio')}</div><div class="grid-2">${panel('Recommended Product Mix',`<div class="donut-row"><div class="donut mix-donut" data-label="5.8 M\A Units"></div><ul class="legend"><li><i style="background:#3888ed"></i>Foundation <b>38% · 2.20 M</b></li><li><i></i>Mascara <b>23% · 1.33 M</b></li><li><i style="background:#f8b339"></i>Lip Gloss <b>20% · 1.16 M</b></li><li><i style="background:#9aa8bc"></i>Moisturizer <b>19% · 1.11 M</b></li></ul></div>`,'','Volume distribution by category')}${panel('Product Mix by Line',`<table class="data-table"><thead><tr><th>Line</th><th>Primary Category</th><th>SKUs</th><th>Volume</th><th>Mix Share</th><th>PV Changes</th></tr></thead><tbody>${state.plan.lines.map((l,i)=>`<tr><td><b>${l.line}</b></td><td>${['Foundation','Moisturizer','Mascara','Cleanser','Lip Gloss','Mixed'][i]}</td><td>${l.eligible_skus}</td><td>${(1.35-i*.15).toFixed(2)} M</td><td>${23-i*2}%</td><td>${Math.max(2,8-i)}</td></tr>`).join('')}</tbody></table>`)}</div><div class="grid-3" style="margin-top:10px">${panel('High-Volume Products',`<ul class="ranked-list"><li><b>1</b><span>Longwear Foundation<small>620K units · F04</small></span></li><li><b>2</b><span>Volume Mascara<small>480K units · F02</small></span></li><li><b>3</b><span>Hydra Moisturizer<small>450K units · F07</small></span></li></ul>`)}${panel('Mix Improvements',`<ul class="check-list"><li>Foundation consolidated on F04</li><li>Lip Gloss campaign moved to F05</li><li>High-speed PV used for 18 priority SKUs</li><li>Category transitions reduced by 31%</li></ul>`)}${panel('Demand Coverage',`<strong class="tab-big-number">100%</strong><p>All confirmed demand is planned inside the four-week horizon.</p><div class="progress"><i style="width:100%"></i></div>`)}</div></div>`}
function strategyChangeovers(){return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('⇄','Total Changeovers','68','49','↓ 27.9%')}${splitKpi('♨','Full Cleans','18','10','↓ 44.4%')}${splitKpi('◷','Setup Hours','142','96','↓ 32.4%')}${kpi('▥','Cost Released','$0.7M','From fewer setup and cleaning events')}</div><div class="grid-2 wide-left">${panel('Changeovers by Line',`<div class="utilization-chart">${state.plan.lines.map(l=>`<div><b>${l.line}</b><span><i style="width:${l.changeovers[0]/20*100}%"></i><em>${l.changeovers[0]}</em></span><span><i class="recommended" style="width:${l.changeovers[1]/20*100}%"></i><em>${l.changeovers[1]}</em></span></div>`).join('')}</div>`,'','Current versus recommended sequence')}${panel('Event Mix',`<div class="donut-row"><div class="donut event-donut" data-label="49\A Events"></div><ul class="legend"><li><i style="background:#ff7a17"></i>Standard changeover 57%</li><li><i style="background:#ef5155"></i>Full clean 20%</li><li><i style="background:#3888ed"></i>Line clearance 23%</li></ul></div>`)}</div>${panel('Highest-Impact Sequence Changes',`<table class="data-table"><thead><tr><th>Line</th><th>Current Transition</th><th>Recommended Transition</th><th>Events Removed</th><th>Hours Saved</th><th>Cost Saved ($K)</th><th>Reason</th></tr></thead><tbody><tr><td>F04</td><td>Foundation → Mascara</td><td>Foundation → Lip Gloss</td><td class="good">3</td><td class="good">14</td><td class="good">$1.1K</td><td>Same colour family</td></tr><tr><td>F07</td><td>Sunscreen → Moisturizer</td><td>Moisturizer → Serum</td><td class="good">4</td><td class="good">11</td><td class="good">$0.9K</td><td>No full clean</td></tr><tr><td>F02</td><td>Lip Balm → Foundation</td><td>Foundation → Mascara</td><td class="good">3</td><td class="good">9</td><td class="good">$0.7K</td><td>Campaign consolidation</td></tr></tbody></table>`)}</div>`}
function strategyInventory(){const m=state.plan.metrics;return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('◇','Average Inventory','$3.2M',`$${m.inventory_recommended}M`,`↓ ${metricDelta(3.2,m.inventory_recommended)}`)}${kpi('◷','Average Days on Hand','18.6 days','21.4 days current','↓ 2.8 days')}${kpi('△','Shelf-Life Risk','3 SKUs','7 SKUs current','↓ 4 SKUs')}${kpi('▦','Holding Cost','$0.58M','$0.72M current','↓ 19.4%')}</div><div class="grid-2">${panel('Inventory Value by Week',barChart([['Week 1',3.2,2.9],['Week 2',3.1,2.7],['Week 3',3.0,2.5],['Week 4',2.9,2.4]],3.5),'','Recommended inventory declines through the horizon.')}${panel('Inventory by Category',`<table class="data-table"><thead><tr><th>Category</th><th>Current Value</th><th>Recommended</th><th>Days on Hand</th><th>Change</th></tr></thead><tbody><tr><td>Foundation</td><td>$1.15M</td><td>$0.92M</td><td>19.2</td><td class="good">-20.0%</td></tr><tr><td>Mascara</td><td>$0.83M</td><td>$0.69M</td><td>17.4</td><td class="good">-16.9%</td></tr><tr><td>Lip Gloss</td><td>$0.67M</td><td>$0.52M</td><td>16.8</td><td class="good">-22.4%</td></tr><tr><td>Moisturizer</td><td>$0.55M</td><td>$0.47M</td><td>20.1</td><td class="good">-14.5%</td></tr></tbody></table>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Inventory Policy',`<ul class="check-list"><li>Safety stock protected for priority SKUs</li><li>MOQ increases remain below storage limits</li><li>Shelf-life windows enforced</li></ul>`)}${panel('Working Capital Released',`<strong class="tab-big-number">$${(3.2-m.inventory_recommended).toFixed(1)}M</strong><p>Average working capital reduction in the recommended plan.</p>`)}${panel('Risk Watchlist',`<ul class="capacity-list"><li><span><b>MSC-002</b><small>Short shelf-life</small></span><em class="watch">Monitor</em></li><li><span><b>LPG-003</b><small>MOQ increased 250%</small></span><em class="healthy">Within limit</em></li></ul>`)}</div></div>`}
function strategyCosts(){const m=state.plan.metrics;return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('▦','Total Cost','$12.4M',`$${m.recommended_cost}M`,`↓ ${metricDelta(12.4,m.recommended_cost)}`)}${splitKpi('⚙','Setup & Cleaning','$2.1M','$1.4M','↓ 33.3%')}${splitKpi('◇','Inventory Holding','$3.2M',`$${m.inventory_recommended}M`,`↓ ${metricDelta(3.2,m.inventory_recommended)}`)}${splitKpi('▥','Production & Labour','$6.8M','$6.4M','↓ 5.9%')}</div><div class="grid-2">${panel('Cost Breakdown Comparison',barChart([['Production',6.2,5.8],['Setup',2.1,1.4],['Inventory',3.2,m.inventory_recommended],['Labour',.6,.6],['Other',.3,.4]],7),'','$M by cost component')}${panel('Savings Contribution',`<div class="donut-row"><div class="donut savings-donut" data-label="$${(12.4-m.recommended_cost).toFixed(1)}M\A Savings"></div><ul class="legend"><li><i style="background:#3888ed"></i>PV assignment 33%</li><li><i></i>Sequencing 28%</li><li><i style="background:#f8b339"></i>MOQ optimization 25%</li><li><i style="background:#9aa8bc"></i>Line balancing 14%</li></ul></div>`)}</div>${panel('Cost Detail by Line',`<table class="data-table"><thead><tr><th>Line</th><th>Current Cost</th><th>Recommended</th><th>Production</th><th>Setup</th><th>Inventory</th><th>Savings</th><th>Primary Driver</th></tr></thead><tbody>${state.plan.lines.map(l=>`<tr><td><b>${l.line}</b></td><td>$${l.cost[0]}M</td><td>$${l.cost[1]}M</td><td>$${(l.cost[1]*.55).toFixed(2)}M</td><td>$${(l.cost[1]*.18).toFixed(2)}M</td><td>$${(l.cost[1]*.22).toFixed(2)}M</td><td class="good">$${(l.cost[0]-l.cost[1]).toFixed(1)}M</td><td>${l.change}</td></tr>`).join('')}</tbody></table>`)}</div>`}
function campaignStrategyMix(){const m=state.plan.metrics,products=state.plan.campaign.products;return `<div class="tab-content-enter"><div class="kpi-grid">${kpi('◇','Active Products','3','Hydrating Lotion · Foundation · Mascara')}${kpi('▦','Target Volume',`${fmt(m.target_volume)} units`,'Marketing requirement')}${kpi('▥','Recommended Volume',`${fmt(m.recommended_volume)} units`,`${m.recommended_achievement}% achievement`)}${kpi('⌘','Volume Improvement',`+${fmt(m.recommended_volume-m.current_volume)}`,'vs current manufacturing plan')}</div><div class="grid-2">${panel('Recommended Product Mix',`<div class="product-mix-bars">${products.map(item=>`<div><span>${item.name}</span><i><em style="width:${item.recommendedVolume/m.recommended_volume*100}%;background:${item.color}"></em></i><b>${fmt(item.recommendedVolume)}</b></div>`).join('')}</div>`,'','Recommended units by active campaign product')}${panel('Product Plan by Line',`<table class="data-table"><thead><tr><th>Product</th><th>Line</th><th>PV</th><th>Target</th><th>Current</th><th>Recommended</th><th>Gap Remaining</th></tr></thead><tbody>${products.map(item=>`<tr><td><b>${item.name}</b></td><td>${item.line}</td><td>${item.pv}</td><td>${fmt(item.targetVolume)}</td><td>${fmt(item.currentVolume)}</td><td>${fmt(item.recommendedVolume)}</td><td class="${item.targetVolume-item.recommendedVolume?'warn':'good'}">${fmt(item.targetVolume-item.recommendedVolume)}</td></tr>`).join('')}</tbody></table>`)}</div><div class="grid-3" style="margin-top:10px">${products.map((item,index)=>panel(item.name,`<strong class="tab-big-number">${item.recommendedAchievement.toFixed(1)}%</strong><p>${fmt(item.recommendedVolume)} recommended of ${fmt(item.targetVolume)} target units.</p><div class="progress"><i style="width:${item.recommendedAchievement}%;background:${item.color}"></i></div><small>${item.targetVolume-item.recommendedVolume?`${fmt(item.targetVolume-item.recommendedVolume)} units remain constrained`:'Target fully achieved'}</small>`)).join('')}</div></div>`}
function campaignStrategyTab(){const m=state.plan.metrics,products=state.plan.campaign.products,lines=state.plan.lines;if(state.strategyTab==='mix')return campaignStrategyMix();if(state.strategyTab==='metrics')return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`+${m.achievement_gain} pp`)}${splitKpi('▥','Achieved Volume',fmt(m.current_volume),fmt(m.recommended_volume),`+${fmt(m.recommended_volume-m.current_volume)}`)}${splitKpi('◷','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`-${m.setup_current-m.setup_recommended} hrs`)}${splitKpi('▦','Production Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`-$${(m.current_cost-m.recommended_cost).toFixed(2)}M`)}</div>${panel('Campaign KPI Reconciliation',`<div class="campaign-achievement-table"><header><span>Product</span><span>Target</span><span>Current Plan</span><span>Recommended Plan</span><span>Achievement</span></header>${products.map(item=>`<div><b>${item.name}<small>${item.line} · ${item.pv}</small></b><span>${fmt(item.targetVolume)}</span><span>${fmt(item.currentVolume)}</span><span>${fmt(item.recommendedVolume)}</span><i><em style="width:${item.recommendedAchievement}%"></em></i></div>`).join('')}</div>`,'','Every KPI uses the same active four-week campaign baseline.')}</div>`;if(state.strategyTab==='utilization')return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('▤','Network Utilization',`${m.utilisation_current}%`,`${m.utilisation_recommended}%`,`+${m.utilisation_recommended-m.utilisation_current} pp`)}${kpi('▥','Active Lines','3','F04 · F07 · F02')}${kpi('◎','Target Breaches','0','Hard ceilings enforced','','good')}${kpi('◷','Capacity Horizon','4 weeks','Same baseline and recommendation')}</div>${panel('Utilization by Product Line',`<div class="utilization-chart">${lines.map((line,index)=>`<div><b>${line.line}</b><span><i style="width:${line.utilisation[0]}%"></i><em>${line.utilisation[0]}%</em></span><span><i class="recommended" style="width:${line.utilisation[1]}%"></i><em>${line.utilisation[1]}%</em></span></div>`).join('')}</div>`,'','Current plan versus recommended plan.')}</div>`;if(state.strategyTab==='changeovers')return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('⇄','Changeovers',m.changeovers_current,m.changeovers_recommended,`-${m.changeovers_current-m.changeovers_recommended} events`)}${splitKpi('◷','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`-${m.setup_current-m.setup_recommended} hrs`)}${kpi('▥','Campaign Products','3','Hydrating Lotion · Foundation · Mascara')}${kpi('✓','Constraint Violations','0','Recommended sequence','','good')}</div>${panel('Changeovers by Active Line',`<div class="utilization-chart">${lines.map(line=>`<div><b>${line.line}</b><span><i style="width:${line.changeovers[0]/Math.max(1,m.changeovers_current)*250}%"></i><em>${line.changeovers[0]}</em></span><span><i class="recommended" style="width:${line.changeovers[1]/Math.max(1,m.changeovers_current)*250}%"></i><em>${line.changeovers[1]}</em></span></div>`).join('')}</div>`,'','Compatible product campaigns reduce transition effort.')}</div>`;if(state.strategyTab==='inventory')return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,m.inventory_recommended>m.inventory_current?'↑ service trade-off':'↓ working capital')}${kpi('◎','MOQ Mode',state.moqMode==='fixed'?'Fixed':'Optimized','Configured in Campaign Brief')}${kpi('▥','Target Ceiling','100% maximum','Applied per product')}${kpi('✓','Shelf-life Checks','Passed','All 3 products','','good')}</div>${panel('Inventory and MOQ by Product',`<table class="data-table"><thead><tr><th>Product</th><th>Target Volume</th><th>Current MOQ</th><th>Recommended MOQ</th><th>Recommended Volume</th><th>Trade-off</th></tr></thead><tbody>${products.map(item=>`<tr><td><b>${item.name}</b></td><td>${fmt(item.targetVolume)}</td><td>${fmt(item.currentMoq)}</td><td>${fmt(item.recommendedMoq)}</td><td>${fmt(item.recommendedVolume)}</td><td>${item.recommendedMoq>item.currentMoq?'Fewer setups / more inventory':'Inventory controlled'}</td></tr>`).join('')}</tbody></table>`)}</div>`;return `<div class="tab-content-enter"><div class="kpi-grid">${splitKpi('▦','Production Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`-$${(m.current_cost-m.recommended_cost).toFixed(2)}M`)}${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,m.inventory_recommended>m.inventory_current?'↑ trade-off':'↓ improvement')}${splitKpi('◷','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`-${m.setup_current-m.setup_recommended} hrs`)}${splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`+${m.achievement_gain} pp`)}</div>${panel('Cost and Service Trade-off',costBreakdownChart(),'','Savings and trade-offs reconcile to the active three-product campaign.')}</div>`}
function campaignStrategyInsights(){const m=state.plan.metrics,products=state.plan.campaign.products,lines=state.plan.lines,totalTarget=m.target_volume,costSaving=Number((m.current_cost-m.recommended_cost).toFixed(2)),inventoryDelta=Number((m.inventory_recommended-m.inventory_current).toFixed(2)),weeklyCurrent=[.24,.27,.25,.24].map(x=>Math.round(m.current_volume*x)),weeklyRecommended=[.23,.25,.27,.25].map(x=>Math.round(m.recommended_volume*x));if(state.strategyTab==='metrics')return `<div class="tab-content-enter strategy-detail"><div class="kpi-grid">${splitKpi('◎','Volume Achievement',`${m.current_achievement}%`,`${m.recommended_achievement}%`,`+${m.achievement_gain} pp`)}${splitKpi('▥','Achieved Volume',fmt(m.current_volume),fmt(m.recommended_volume),`+${fmt(m.recommended_volume-m.current_volume)}`)}${splitKpi('◷','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`-${m.setup_current-m.setup_recommended} hrs`)}${splitKpi('▦','Production Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`-$${costSaving}M`)}</div><div class="grid-2 wide-left">${panel('Volume Target Achievement by Product',`<div class="strategy-product-bars">${products.map(item=>`<article><header><span><i style="background:${item.color}"></i><b>${item.name}</b><small>${item.sku} · ${item.line}</small></span><strong>${item.recommendedAchievement.toFixed(1)}%</strong></header><div class="comparison-track"><i class="current" style="width:${item.currentAchievement}%"></i><i class="recommended" style="width:${item.recommendedAchievement}%"></i></div><footer><span>Current ${item.currentAchievement.toFixed(1)}%</span><span>Recommended ${item.recommendedAchievement.toFixed(1)}%</span><b>${fmt(item.targetVolume-item.recommendedVolume)} gap</b></footer></article>`).join('')}</div>`,'','Current manufacturing baseline compared with the optimized plan.')}${panel('Plan Value Bridge',`<div class="strategy-value-ring" style="--score:${m.recommended_achievement}"><div><strong>${m.recommended_achievement}%</strong><span>target achieved</span></div></div><div class="strategy-mini-metrics"><article><span>Additional volume</span><b>+${fmt(m.recommended_volume-m.current_volume)}</b><small>units</small></article><article><span>Cost released</span><b>$${costSaving}M</b><small>four-week horizon</small></article><article><span>Setup time released</span><b>${m.setup_current-m.setup_recommended} hrs</b><small>productive capacity</small></article></div>`,'strategy-value-card','Service improvement and efficiency value delivered together.')}</div>${panel('Executive KPI Reconciliation',`<table class="data-table strategy-data-table"><thead><tr><th>Decision metric</th><th>Current plan</th><th>Recommended plan</th><th>Net movement</th><th>Business interpretation</th><th>Status</th></tr></thead><tbody><tr><td><b>Volume target achievement</b></td><td>${m.current_achievement}%</td><td>${m.recommended_achievement}%</td><td class="good">+${m.achievement_gain} pp</td><td>Closes the marketing requirement gap</td><td><span class="tag green">Improved</span></td></tr><tr><td><b>Achieved volume</b></td><td>${fmt(m.current_volume)}</td><td>${fmt(m.recommended_volume)}</td><td class="good">+${fmt(m.recommended_volume-m.current_volume)}</td><td>More feasible production inside the same horizon</td><td><span class="tag green">Improved</span></td></tr><tr><td><b>Line utilization</b></td><td>${m.utilisation_current}%</td><td>${m.utilisation_recommended}%</td><td class="good">+${m.utilisation_recommended-m.utilisation_current} pp</td><td>Shared capacity is used more productively</td><td><span class="tag green">Improved</span></td></tr><tr><td><b>Average inventory</b></td><td>$${m.inventory_current}M</td><td>$${m.inventory_recommended}M</td><td class="${inventoryDelta>0?'warn':'good'}">${inventoryDelta>0?'+':''}$${inventoryDelta}M</td><td>${inventoryDelta>0?'Service gain requires a controlled inventory trade-off':'Working capital is released'}</td><td><span class="tag ${inventoryDelta>0?'orange':'green'}">${inventoryDelta>0?'Trade-off':'Improved'}</span></td></tr><tr><td><b>Production cost</b></td><td>$${m.current_cost}M</td><td>$${m.recommended_cost}M</td><td class="good">-$${costSaving}M</td><td>PV, MOQ, and sequencing efficiencies</td><td><span class="tag green">Improved</span></td></tr></tbody></table>`,'strategy-full-table')}</div>`;
if(state.strategyTab==='utilization')return `<div class="tab-content-enter strategy-detail"><div class="kpi-grid">${splitKpi('▤','Network Utilization',`${m.utilisation_current}%`,`${m.utilisation_recommended}%`,`+${m.utilisation_recommended-m.utilisation_current} pp`)}${kpi('▥','Active Lines','3','F04 · F07 · F02')}${kpi('◷','Capacity Released',`${m.setup_current-m.setup_recommended} hrs`,'From fewer setups and transitions','','good')}${kpi('✓','Capacity Violations','0','All recommendations feasible','','good')}</div><div class="grid-2">${panel('Line Utilization Comparison',`<div class="strategy-axis"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><div class="strategy-line-bars">${lines.map((line,index)=>`<article><header><b>${line.line}</b><span>${products[index].name}</span><strong>${line.utilisation[1]}%</strong></header><div><i class="current" style="width:${line.utilisation[0]}%"><em>${line.utilisation[0]}%</em></i></div><div><i class="recommended" style="width:${line.utilisation[1]}%"><em>${line.utilisation[1]}%</em></i></div><footer><span>Current</span><span>Recommended</span><b class="good">+${line.utilisation[1]-line.utilisation[0]} pp</b></footer></article>`).join('')}</div>`,'','Percentage of available four-week line capacity.')}${panel('Capacity Allocation by Product',`<div class="capacity-allocation">${products.map((item,index)=>{const hours=Math.round(720*lines[index].utilisation[1]/100),available=720-hours;return `<article><header><i style="background:${item.color}"></i><span><b>${item.name}</b><small>${item.line} · ${item.pv}</small></span><em>${hours} hrs planned</em></header><div class="capacity-donut" style="--used:${lines[index].utilisation[1]}"><strong>${lines[index].utilisation[1]}%</strong></div><footer><span>${available} hrs remaining</span><b class="good">Feasible</b></footer></article>`}).join('')}</div>`,'','Recommended productive hours and remaining capacity.')}</div>${panel('Line Capacity Evidence',`<table class="data-table"><thead><tr><th>Line</th><th>Assigned product</th><th>Available hours</th><th>Current hours</th><th>Recommended hours</th><th>Capacity remaining</th><th>Changeovers</th><th>Assessment</th></tr></thead><tbody>${lines.map((line,index)=>{const currentHours=Math.round(720*line.utilisation[0]/100),recommendedHours=Math.round(720*line.utilisation[1]/100);return `<tr><td><b>${line.line}</b></td><td>${products[index].name}</td><td>720</td><td>${currentHours}</td><td>${recommendedHours}</td><td>${720-recommendedHours}</td><td>${line.changeovers[0]} → ${line.changeovers[1]}</td><td><span class="tag green">Within limit</span></td></tr>`}).join('')}</tbody></table>`,'strategy-full-table')}</div>`;
if(state.strategyTab==='mix'){const shares=products.map(item=>item.recommendedVolume/m.recommended_volume*100),gradient=products.map((item,index)=>{const start=shares.slice(0,index).reduce((a,b)=>a+b,0),end=start+shares[index];return `${item.color} ${start}% ${end}%`}).join(',');return `<div class="tab-content-enter strategy-detail"><div class="kpi-grid">${kpi('◇','Active Products','3','One coordinated campaign portfolio')}${kpi('▦','Target Volume',`${fmt(totalTarget)}`,'marketing-requested units')}${kpi('▥','Recommended Volume',`${fmt(m.recommended_volume)}`,`${m.recommended_achievement}% target achievement`)}${kpi('⌘','Volume Uplift',`+${fmt(m.recommended_volume-m.current_volume)}`,'vs current manufacturing plan','','good')}</div><div class="grid-2 wide-right">${panel('Recommended Product Mix',`<div class="strategy-mix-visual"><div class="strategy-mix-donut" style="background:conic-gradient(${gradient})"><div><strong>${fmt(m.recommended_volume)}</strong><span>planned units</span></div></div><ul>${products.map((item,index)=>`<li><i style="background:${item.color}"></i><span><b>${item.name}</b><small>${item.line} · ${item.pv}</small></span><strong>${shares[index].toFixed(1)}%</strong><em>${fmt(item.recommendedVolume)}</em></li>`).join('')}</ul></div>`,'','Share of recommended volume by campaign product.')}${panel('Current vs Recommended Product Volume',`<div class="product-volume-chart">${products.map(item=>`<article><header><span>${item.name}</span><b>${fmt(item.targetVolume)} target</b></header><div class="target"><i class="current" style="width:${item.currentAchievement}%"></i><em>${fmt(item.currentVolume)}</em></div><div class="target"><i class="recommended" style="width:${item.recommendedAchievement}%"></i><em>${fmt(item.recommendedVolume)}</em></div><footer><span>Current plan</span><span>Recommended plan</span><b class="good">+${fmt(item.recommendedVolume-item.currentVolume)}</b></footer></article>`).join('')}</div>`,'','Volume remains at or below each marketing target.')}</div>${panel('Product Mix Decision Table',`<table class="data-table"><thead><tr><th>Product</th><th>Portfolio share</th><th>Target volume</th><th>Current plan</th><th>Recommended plan</th><th>Volume uplift</th><th>Remaining gap</th><th>Primary decision</th></tr></thead><tbody>${products.map((item,index)=>`<tr><td><b>${item.name}</b><small>${item.sku}</small></td><td>${shares[index].toFixed(1)}%</td><td>${fmt(item.targetVolume)}</td><td>${fmt(item.currentVolume)}</td><td>${fmt(item.recommendedVolume)}</td><td class="good">+${fmt(item.recommendedVolume-item.currentVolume)}</td><td class="${item.targetVolume-item.recommendedVolume?'warn':'good'}">${fmt(item.targetVolume-item.recommendedVolume)}</td><td>${item.line} / ${item.pv} · MOQ ${fmt(item.recommendedMoq)}</td></tr>`).join('')}</tbody></table>`,'strategy-full-table')}</div>`}
if(state.strategyTab==='changeovers')return `<div class="tab-content-enter strategy-detail"><div class="kpi-grid">${splitKpi('⇄','Total Changeovers',m.changeovers_current,m.changeovers_recommended,`-${m.changeovers_current-m.changeovers_recommended} events`)}${splitKpi('◷','Setup Time',`${m.setup_current} hrs`,`${m.setup_recommended} hrs`,`-${m.setup_current-m.setup_recommended} hrs`)}${kpi('♨','Full Cleans Avoided','4','Compatible campaign grouping','','good')}${kpi('▦','Setup Cost Released',`$${(costSaving*.42).toFixed(2)}M`,'Estimated contribution to savings','','good')}</div><div class="grid-2 wide-left">${panel('Changeovers by Active Line',`<div class="changeover-chart"><div class="strategy-axis"><span>0</span><span>5</span><span>10</span><span>15</span><span>20</span></div>${lines.map((line,index)=>`<article><header><b>${line.line}</b><span>${products[index].name}</span><strong class="good">-${line.changeovers[0]-line.changeovers[1]}</strong></header><div><i class="current" style="width:${line.changeovers[0]/20*100}%"><em>${line.changeovers[0]}</em></i></div><div><i class="recommended" style="width:${line.changeovers[1]/20*100}%"><em>${line.changeovers[1]}</em></i></div></article>`).join('')}<footer><span><i></i>Current plan</span><span><i></i>Recommended plan</span></footer></div>`,'','Event count after campaign consolidation and resequencing.')}${panel('Product Transition Matrix (hrs)',`<div class="transition-matrix"><header><span>From / To</span>${products.map(item=>`<b>${item.name.replace('New ','').replace('Hydrating ','Hyd. ')}</b>`).join('')}</header>${[['Hyd. Lotion','—','2.0','3.5'],['Foundation','2.0','—','4.0'],['Mascara','3.5','4.0','—']].map(row=>`<div><b>${row[0]}</b>${row.slice(1).map(value=>`<span class="${value==='—'?'na':Number(value)>=3.5?'high':'low'}">${value}</span>`).join('')}</div>`).join('')}</div><div class="matrix-legend"><span><i class="low"></i>Preferred transition</span><span><i class="high"></i>Higher setup effort</span></div>`,'','Lower-hour transitions are prioritized where capacity allows.')}</div>${panel('Sequence Improvement Evidence',`<table class="data-table"><thead><tr><th>Line</th><th>Current pattern</th><th>Recommended pattern</th><th>Events removed</th><th>Hours released</th><th>Operational reason</th><th>Impact</th></tr></thead><tbody>${lines.map((line,index)=>`<tr><td><b>${line.line}</b></td><td>Fragmented ${products[index].name} runs</td><td>Consolidated product campaign</td><td class="good">${line.changeovers[0]-line.changeovers[1]}</td><td class="good">${Math.round((m.setup_current-m.setup_recommended)*(line.changeovers[0]-line.changeovers[1])/Math.max(1,m.changeovers_current-m.changeovers_recommended))}</td><td>${index===0?'Dedicated lotion window':index===1?'Compatible PV and line assignment':'Longer stable mascara runs'}</td><td><span class="tag green">Positive</span></td></tr>`).join('')}</tbody></table>`,'strategy-full-table')}</div>`;
if(state.strategyTab==='inventory')return `<div class="tab-content-enter strategy-detail"><div class="kpi-grid">${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,inventoryDelta>0?'↑ service trade-off':'↓ working capital')}${kpi('◎','MOQ Treatment',state.moqMode==='fixed'?'Fixed':'Optimized','Configured in Campaign Brief')}${kpi('▥','Target Ceiling Breaches','0','Applied independently to all products','','good')}${kpi('✓','Storage & Shelf-life','Within guardrails','All campaign products','','good')}</div><div class="grid-2">${panel('Four-Week Inventory Profile',`<div class="inventory-week-chart">${[1,2,3,4].map((week,index)=>{const current=Number((m.inventory_current*[1.02,1,.96,.91][index]).toFixed(2)),recommended=Number((m.inventory_recommended*[.94,1.05,1,.9][index]).toFixed(2)),max=Math.max(m.inventory_current,m.inventory_recommended)*1.15;return `<article><div><i class="current" style="height:${current/max*100}%"><em>$${current}M</em></i><i class="recommended" style="height:${recommended/max*100}%"><em>$${recommended}M</em></i></div><b>Week ${week}</b></article>`}).join('')}</div><div class="chart-legend"><span><i></i>Current plan</span><span><i></i>Recommended plan</span></div>`,'','Average inventory value across the planning horizon.')}${panel('Inventory Exposure by Product',`<div class="inventory-product-list">${products.map((item,index)=>{const share=item.recommendedVolume/m.recommended_volume,inventory=Number((m.inventory_recommended*share).toFixed(2)),days=Math.round(item.recommendedMoq/(item.recommendedVolume/28));return `<article><header><i style="background:${item.color}"></i><span><b>${item.name}</b><small>MOQ ${fmt(item.recommendedMoq)}</small></span><strong>$${inventory}M</strong></header><div><span>Estimated days of supply</span><b>${days} days</b></div><div><span>Target utilization</span><b>${item.recommendedAchievement.toFixed(1)}%</b></div><footer><span class="tag ${days>5?'orange':'green'}">${days>5?'Monitor':'Healthy'}</span><em>${item.recommendedMoq>item.currentMoq?'Higher MOQ / fewer setups':'Stable lot size'}</em></footer></article>`}).join('')}</div>`,'','Inventory value is allocated by recommended campaign volume.')}</div>${panel('MOQ and Inventory Guardrails',`<table class="data-table"><thead><tr><th>Product</th><th>Current MOQ</th><th>Recommended MOQ</th><th>MOQ change</th><th>Recommended volume</th><th>Target ceiling</th><th>Storage check</th><th>Decision</th></tr></thead><tbody>${products.map(item=>{const change=Math.round((item.recommendedMoq/item.currentMoq-1)*100);return `<tr><td><b>${item.name}</b></td><td>${fmt(item.currentMoq)}</td><td>${fmt(item.recommendedMoq)}</td><td class="${change>0?'warn':'good'}">${change>=0?'+':''}${change}%</td><td>${fmt(item.recommendedVolume)}</td><td>${fmt(item.targetVolume)}</td><td><span class="tag green">Passed</span></td><td>${change>0?'Accept inventory to reduce setup':'Maintain current exposure'}</td></tr>`}).join('')}</tbody></table>`,'strategy-full-table')}</div>`;
return `<div class="tab-content-enter strategy-detail"><div class="kpi-grid">${splitKpi('▦','Production Cost',`$${m.current_cost}M`,`$${m.recommended_cost}M`,`-$${costSaving}M`)}${kpi('◎','Savings Rate',`${metricDelta(m.current_cost,m.recommended_cost)}`,'vs current four-week plan','','good')}${splitKpi('◇','Average Inventory',`$${m.inventory_current}M`,`$${m.inventory_recommended}M`,inventoryDelta>0?'↑ explicit trade-off':'↓ improvement')}${kpi('▥','Incremental Volume',`+${fmt(m.recommended_volume-m.current_volume)}`,'units planned inside targets','','good')}</div><div class="grid-2">${panel('Current vs Recommended Cost Structure',`<div class="stacked-cost-chart">${[['Current plan',m.current_cost,[.5,.19,.22,.05,.04]],['Recommended',m.recommended_cost,[.54,.12,.24,.055,.035]]].map(row=>`<article><header><b>${row[0]}</b><strong>$${row[1]}M</strong></header><div>${row[2].map((share,index)=>`<i style="width:${share*100}%" class="cost-${index}"><span>$${(row[1]*share).toFixed(2)}M</span></i>`).join('')}</div></article>`).join('')}<footer>${['Production','Setup','Inventory','Labor','Other'].map((name,index)=>`<span><i class="cost-${index}"></i>${name}</span>`).join('')}</footer></div>`,'','Cost composition for the same campaign and horizon.')}${panel('Savings Drivers',`<div class="savings-driver-chart">${[['PV selection',costSaving*.31,'Higher run rate and yield'],['MOQ decisions',costSaving*.27,'Fewer batch starts'],['Campaign sequence',costSaving*.29,'Fewer transitions and cleans'],['Line balance',costSaving*.13,'Higher productive utilization']].map((item,index)=>`<article><span>0${index+1}</span><p><b>${item[0]}</b><small>${item[2]}</small></p><i><em style="width:${item[1]/costSaving*100}%"></em></i><strong>$${item[1].toFixed(2)}M</strong></article>`).join('')}</div>`,'','Net contribution to the recommended cost reduction.')}</div><div class="grid-2" style="margin-top:12px">${panel('Weekly Cost Run Rate',`<div class="weekly-cost-chart">${[1,2,3,4].map((week,index)=>{const current=Number((m.current_cost*[.26,.25,.245,.245][index]).toFixed(2)),recommended=Number((m.recommended_cost*[.25,.245,.25,.255][index]).toFixed(2)),max=m.current_cost*.3;return `<article><div><i class="current" style="height:${current/max*100}%"><em>$${current}M</em></i><i class="recommended" style="height:${recommended/max*100}%"><em>$${recommended}M</em></i></div><b>Week ${week}</b></article>`}).join('')}</div><div class="chart-legend"><span><i></i>Current</span><span><i></i>Recommended</span></div>`,'','Cost remains below baseline across the four-week horizon.')}${panel('Cost by Campaign Product',`<table class="data-table"><thead><tr><th>Product</th><th>Volume share</th><th>Current cost</th><th>Recommended cost</th><th>Net saving</th><th>Primary mechanism</th></tr></thead><tbody>${products.map(item=>{const share=item.targetVolume/totalTarget,current=Number((m.current_cost*share).toFixed(2)),recommended=Number((m.recommended_cost*share).toFixed(2));return `<tr><td><b>${item.name}</b></td><td>${(share*100).toFixed(1)}%</td><td>$${current}M</td><td>$${recommended}M</td><td class="good">$${(current-recommended).toFixed(2)}M</td><td>${item.id==='hydrating'?'PV-3 and dedicated F04 window':item.id==='foundation'?'Line reassignment and campaign consolidation':'Longer stable runs and target MOQ'}</td></tr>`}).join('')}</tbody></table>`)}</div></div>`}
function renderStrategyTabs(){if(state.strategyTab==='overview')return renderStrategy();return `${strategyTabBar()}${campaignStrategyInsights()}${footer()}`}

function explainTabBar(){const tabs=[['transition','Transition Reasoning'],['moq','MOQ Reasoning'],['pv','PV Reasoning'],['cost','Cost Breakdown'],['rules','Rule Impact']];return `<div class="view-tabs tab-strip" role="tablist">${tabs.map(([key,label])=>`<button role="tab" aria-selected="${state.explainTab===key}" data-explain-tab="${key}" class="${state.explainTab===key?'active':''}">${label}</button>`).join('')}</div>`}
function explainMOQ(){return `<div class="tab-content-enter">${panel('▦ &nbsp; MOQ Recommendation: LPG-003 · Lip Gloss',`<div class="grid-2 wide-left"><p>The model recommends increasing MOQ from 10,000 to 35,000 units. Fewer setups outweigh the additional inventory holding cost while remaining inside shelf-life and storage limits.</p><div class="score-card"><span>✓</span><div><b class="good">Recommended</b><small>35,000 units on F05</small></div></div></div>`)}<div class="kpi-grid five" style="margin-top:10px">${splitKpi('▧','MOQ','10,000','35,000','↑ 250%')}${splitKpi('⚙','Setups per Month','12','4','↓ 8 setups')}${splitKpi('▦','Setup Cost','$9.6K','$3.2K','↓ $6.4K')}${splitKpi('◇','Inventory Cost','$1.2K','$2.1K','↑ $0.9K')}${kpi('▥','Net Impact','$5.5K saved','Per planning horizon','','good')}</div><div class="grid-2">${panel('Cost Trade-off',`<div class="tradeoff"><span class="optimal"><b>Optimal MOQ<br>35,000 units</b></span></div><p style="text-align:center">Lot size (units)</p>`,'','Why 35,000 units is the economic optimum')}${panel('Alternative MOQ Comparison',`<table class="data-table"><thead><tr><th>MOQ</th><th>Setups</th><th>Setup Cost ($K)</th><th>Inventory Cost ($K)</th><th>Total Relevant Cost ($K)</th><th>Selected</th></tr></thead><tbody><tr><td>10,000</td><td>12</td><td>$9.6K</td><td>$1.2K</td><td>$10.8K</td><td>○</td></tr><tr><td>20,000</td><td>7</td><td>$5.6K</td><td>$1.6K</td><td>$7.2K</td><td>○</td></tr><tr class="recommended"><td><b>35,000</b></td><td>4</td><td>$3.2K</td><td>$2.1K</td><td><b>$5.3K</b></td><td class="good">●</td></tr><tr><td>50,000</td><td>3</td><td>$2.4K</td><td>$3.5K</td><td>$5.9K</td><td>○</td></tr></tbody></table>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Constraints Checked',`<ul class="check-list"><li>Shelf life: 90 days</li><li>Storage capacity: available</li><li>Batch multiple: 5,000 units</li><li>Demand coverage: 100%</li></ul>`)}${panel('Sensitivity',`<p>The recommendation remains 35,000 units across demand changes from −8% to +12%.</p><div class="progress"><i style="width:86%"></i></div>`)}${panel('Next Actions',`<ul class="action-list"><li data-jump="moq">Open MOQ workspace</li><li data-jump="scenario">Test a lower-MOQ scenario</li><li>Export calculation detail</li></ul>`)}</div></div>`}
function explainPV(){return `<div class="tab-content-enter">${panel('▥ &nbsp; PV Recommendation: FND-001 · Foundation',`<div class="grid-2 wide-left"><p>PV-3 is selected because it combines the highest run rate and yield with the lowest unit and setup cost on line F04. The change is feasible without new tooling.</p><div class="score-card"><span>✓</span><div><b class="good">PV-3 Recommended</b><small>Line F04 · 98% yield</small></div></div></div>`)}<div class="kpi-grid five" style="margin-top:10px">${kpi('▥','Recommended PV','PV-3','Current assignment: PV-1')}${kpi('⌁','Run Rate','600 units/hr','PV-1: 450 units/hr','▲ 33.3%')}${kpi('✓','Yield','98%','PV-1: 95%','▲ 3 pp')}${kpi('▦','Unit Cost','$12.50','PV-1: $18.00','▼ 30.6%')}${kpi('◇','Order Impact','$4.8K saved','Across planned volume','','good')}</div><div class="grid-2 wide-left">${panel('Production Version Comparison',`<table class="data-table"><thead><tr><th>PV</th><th>Eligible Line</th><th>Run Rate</th><th>Yield</th><th>Setup Time</th><th>Unit Cost ($/unit)</th><th>Total Cost ($K)</th><th>Rank</th></tr></thead><tbody><tr><td>PV-1</td><td>F04</td><td>450</td><td>95%</td><td>4.0 hrs</td><td>$18.0</td><td>$32K</td><td>3</td></tr><tr><td>PV-2</td><td>F04/F07</td><td>520</td><td>96%</td><td>3.0 hrs</td><td>$15.0</td><td>$25K</td><td>2</td></tr><tr class="recommended"><td><b>PV-3</b></td><td>F04</td><td><b>600</b></td><td><b>98%</b></td><td><b>2.0 hrs</b></td><td><b>$12.5</b></td><td><b>$16.5K</b></td><td class="good">1</td></tr></tbody></table>`)}${panel('Decision Drivers',`<div class="driver-bars"><div><span>Run-rate advantage</span><i><em style="width:92%"></em></i><b>+18.2</b></div><div><span>Yield improvement</span><i><em style="width:74%"></em></i><b>+14.6</b></div><div><span>Line compatibility</span><i><em style="width:68%"></em></i><b>+13.4</b></div><div><span>Setup reduction</span><i><em style="width:55%"></em></i><b>+10.8</b></div><div><span>Tooling availability</span><i><em class="negative" style="width:18%"></em></i><b>-3.5</b></div></div>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Eligibility Checks',`<ul class="check-list"><li>F04 capability match</li><li>Tooling available</li><li>Quality specification met</li><li>Capacity reserved</li></ul>`)}${panel('Recommendation Confidence',`<strong class="tab-big-number">96%</strong><p>Based on cost, capacity, yield, and technical feasibility.</p><div class="progress"><i style="width:96%"></i></div>`)}${panel('Next Actions',`<ul class="action-list"><li data-jump="pv">Open PV prioritisation</li><li>Compare PV-2 sensitivity</li><li>Review technical route</li></ul>`)}</div></div>`}
function explainCost(){return `<div class="tab-content-enter">${panel('▦ &nbsp; Cost Reduction Explanation',`<p>The recommended plan reduces total order cost from $12.4M to $10.8M. Savings are created jointly by PV reassignment, higher economic MOQs, fewer cleaning events, and better line balance.</p>`)}<div class="kpi-grid five" style="margin-top:10px">${kpi('▦','Total Savings','$1.6M','12.9% below current plan','','good')}${kpi('▥','PV Mix','$0.52M','32.5% of savings')}${kpi('▧','MOQ','$0.40M','25.0% of savings')}${kpi('⇄','Sequencing','$0.45M','28.1% of savings')}${kpi('◇','Line Balance','$0.23M','14.4% of savings')}</div><div class="grid-2">${panel('Cost Waterfall',`<div class="waterfall"><div class="total" style="height:83%"><b>12.4</b><span>Current</span></div><div style="height:20%"><b>-0.52</b><span>PV Mix</span></div><div style="height:17%"><b>-0.40</b><span>MOQ</span></div><div style="height:18%"><b>-0.45</b><span>Sequence</span></div><div style="height:10%"><b>-0.23</b><span>Balance</span></div><div class="final" style="height:72%"><b>10.8</b><span>Recommended</span></div></div>`)}${panel('Savings Evidence',`<table class="data-table"><thead><tr><th>Driver</th><th>Mechanism</th><th>Gross Savings ($M)</th><th>Offset ($M)</th><th>Net Savings ($M)</th></tr></thead><tbody><tr><td>PV mix</td><td>Lower unit cost and higher yield</td><td>$0.58M</td><td>$0.06M</td><td class="good">$0.52M</td></tr><tr><td>MOQ</td><td>Fewer batches and setups</td><td>$0.70M</td><td>$0.30M inventory</td><td class="good">$0.40M</td></tr><tr><td>Sequencing</td><td>19 fewer changeovers</td><td>$0.49M</td><td>$0.04M</td><td class="good">$0.45M</td></tr><tr><td>Line balance</td><td>Higher productive utilization</td><td>$0.23M</td><td>—</td><td class="good">$0.23M</td></tr></tbody></table>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Assumption Sensitivity',`<p>Savings remain above $1.2M if labour and cleaning rates vary by ±15%.</p><div class="progress"><i style="width:88%"></i></div>`)}${panel('Largest Saving Line',`<strong class="tab-big-number">F04</strong><p>$0.4M improvement through sequence and PV changes.</p>`)}${panel('Next Actions',`<ul class="action-list"><li data-jump="cost">Open Cost Analysis</li><li data-jump="scenario">Stress-test cost assumptions</li><li>Export cost evidence</li></ul>`)}</div></div>`}
function explainRules(){const active=state.plan.constraints.filter(c=>c.active);return `<div class="tab-content-enter">${panel('♢ &nbsp; Rule Impact on Recommended Plan',`<div class="grid-2 wide-left"><p>${active.length} active operational constraints were applied during optimization. They add setup time and cost, but eliminate plan violations and protect GMP, allergen, capacity, and scheduling requirements.</p><div class="score-card"><span>✓</span><div><b class="good">0 violations</b><small>Recommended plan is compliant</small></div></div></div>`)}<div class="kpi-grid five" style="margin-top:10px">${kpi('♢','Active Rules',`${active.length} of 12`,'Included in solve')}${kpi('✓','Violations','0','5 in unconstrained plan')}${kpi('◷','Setup Impact','+12 hrs','Compared with unconstrained optimum')}${kpi('▦','Cost Impact','+$0.4M','Compliance premium')}${kpi('▥','Feasibility','100%','All production orders feasible','','good')}</div><div class="grid-2 wide-left">${panel('Active Rule Decisions',`<table class="data-table"><thead><tr><th>Rule</th><th>Type</th><th>Impact</th><th>Plan Decision</th><th>Compliance</th></tr></thead><tbody>${active.map(c=>`<tr><td><b>${c.name}</b></td><td>${c.type}</td><td><span class="impact-${c.impact.toLowerCase()}">${c.impact}</span></td><td>${c.id==='R-001'?'10 full cleans retained':c.id==='R-003'?'Compatible colours grouped':c.id==='R-006'?'Shared assets deconflicted':'Maintenance window respected'}</td><td class="good">● Passed</td></tr>`).join('')}</tbody></table>`)}${panel('Rule Impact Summary',`<div class="driver-bars"><div><span>Cleaning validation</span><i><em class="negative" style="width:88%"></em></i><b>+$0.19M</b></div><div><span>Allergen carryover</span><i><em class="negative" style="width:61%"></em></i><b>+$0.12M</b></div><div><span>Colour family</span><i><em class="negative" style="width:34%"></em></i><b>+$0.06M</b></div><div><span>Line availability</span><i><em class="negative" style="width:18%"></em></i><b>+$0.03M</b></div></div>`)}</div><div class="grid-3" style="margin-top:10px">${panel('Compliance Value',`<strong class="tab-big-number">5 → 0</strong><p>Constraint violations eliminated by the recommended plan.</p>`)}${panel('Most Restrictive Rule',`<strong class="tab-big-number">GMP Clean</strong><p>Controls 31 transitions and 10 full-clean events.</p>`)}${panel('Next Actions',`<ul class="action-list"><li data-jump="constraints">Manage constraints</li><li data-jump="scenario">Compare unconstrained scenario</li><li>Export rule audit</li></ul>`)}</div></div>`}
function renderExplainTabs(){if(state.explainTab==='transition')return renderExplain();const content={moq:explainMOQ,pv:explainPV,cost:explainCost,rules:explainRules}[state.explainTab]();return `${explainTabBar()}${content}${footer()}`}

function render(){const root=$('#m2-content');const fn={launch:renderCampaignBrief,strategy:renderStrategyTabs,pv:()=>decisionStrip('pv')+renderPVWorkspace(),moq:renderMOQWorkspace,campaign:()=>decisionStrip('campaign')+renderCampaignPlan(),cost:renderCost,scenario:renderManufacturingReview,constraints:renderConstraints,explain:()=>decisionStrip('explain')+renderExplainTabs(),review:renderReview,model:renderModel,settings:renderSettings}[state.view]||renderCampaignBrief;const context=!['launch','model','settings'].includes(state.view)?launchContextBar():'';root.innerHTML=context+fn();if(!['moq','pv'].includes(state.view))refreshViewKpis();if(state.view==='cost'){enhanceCostBreakdown();enhanceCostFooter()}if(state.view==='constraints')enhanceConstraintFooter();if(state.view==='strategy'&&state.strategyTab==='overview'){enhanceStrategyOverview();enhanceCampaignStrategy()}if(state.view==='scenario')enhanceManufacturingReview();bindView();}
function setView(name){state.view=name;$$('.m2-nav button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const [title,subtitle]=views[name];$('#m2-heading').textContent=title;$('#m2-subtitle').textContent=subtitle;$('#m2-breadcrumb').innerHTML=`Project PULSE <span>/</span> Module 2 <span>/</span> ${title}`;$('#solve-plan').textContent=name==='review'?'✓  Approve Plan':name==='model'?'▷  Run Model':name==='launch'?'Optimize Plan':name==='scenario'||name==='constraints'?'↻  Resolve Plan':'↻  Re-solve Plan';$('#m2-sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function toast(message){const el=$('#m2-toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function readReviewOptions(){return {...state.reviewOptions,moq_adjustment:Number($('#review-moq')?.value??state.reviewOptions.moq_adjustment),capacity:Number($('#review-capacity')?.value??state.reviewOptions.capacity),line_constraint:$('#review-line')?.value??state.reviewOptions.line_constraint,freeze_days:Number($('#review-freeze')?.value??state.reviewOptions.freeze_days),max_campaign:Number($('#review-campaign')?.value??state.reviewOptions.max_campaign),strict_due_dates:$('#review-strict')?.checked??state.reviewOptions.strict_due_dates}}
function showOverlay(title,messages,mode='resolve'){const overlay=$('#m2-overlay');if(!overlay)return()=>{};const heading=$('#m2-overlay-title')||$('h3',overlay),progress=$('#m2-progress'),card=$(':scope > div',overlay);let visual=$('.m2-overlay-visual',overlay);if(!visual){visual=document.createElement('div');visual.className='m2-overlay-visual';heading?.insertAdjacentElement('afterend',visual)}overlay.classList.remove('mode-build','mode-resolve');overlay.classList.add(`mode-${mode}`);visual.innerHTML=mode==='build'?`<div class="build-flow">${[['01','Launches'],['02','PV'],['03','MOQ'],['04','Sequence'],['05','Cost']].map((item,index)=>`<div style="--step:${index}"><span>${item[0]}</span><b>${item[1]}</b></div>${index<4?'<i>→</i>':''}`).join('')}</div><div class="factory-motion"><i></i><i></i><i></i><span></span></div>`:`<div class="resolve-motion"><span></span><span></span><span></span><strong>Recalculating</strong></div>`;if(heading)heading.textContent=title;if(progress)progress.textContent=messages[0];overlay.classList.remove('hidden');card?.setAttribute('aria-busy','true');let index=0;const timer=setInterval(()=>{if(progress)progress.textContent=messages[++index%messages.length]},mode==='build'?1500:650);return ()=>{clearInterval(timer);overlay.classList.add('hidden');card?.removeAttribute('aria-busy')}}
async function buildManufacturingPlan(){const close=showOverlay('Optimizing four-week plan',['Reading marketing volume and MOQ targets…','Comparing the current manufacturing baseline…','Selecting feasible production versions and lines…','Optimizing MOQs and campaign sequence…','Checking target ceilings and constraints…','Preparing the recommended plan…'],'build');try{await new Promise(resolve=>setTimeout(resolve,10000));state.solutionVariant=0;state.previousMetrics=null;state.plan=applyLaunchScenario(state.basePlan,0,state.reviewOptions);setView('strategy');toast(`Recommended plan reaches ${state.plan.metrics.recommended_achievement}% volume target achievement`)}finally{close()}}
async function solve(options={}){state.reviewOptions={...state.reviewOptions,...options};const before=clone(state.plan.metrics),close=showOverlay('Resolving adjusted plan',['Applying changed constraints…','Recalculating capacity and sequence…','Updating cost and recommendations…'],'resolve');try{const payload={scenario_name:'Manufacturing Review',moq_adjustment:Number(state.reviewOptions.moq_adjustment||0),active_constraints:state.plan.constraints.filter(c=>c.active).length,strict_due_dates:Boolean(state.reviewOptions.strict_due_dates)};const [requestResult]=await Promise.allSettled([fetch('/api/module2/solve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),new Promise(resolve=>setTimeout(resolve,2600))]);if(requestResult.status==='rejected')throw requestResult.reason;const response=requestResult.value;if(!response.ok)throw new Error('Unable to resolve plan');const constraints=clone(state.plan.constraints),responsePlan=await response.json();responsePlan.constraints=constraints;state.basePlan=clone(responsePlan);state.solutionVariant=(state.solutionVariant+1)%3;state.plan=applyLaunchScenario(responsePlan,state.solutionVariant,state.reviewOptions);state.previousMetrics=before;render();toast(`${state.plan.launch_context.label} loaded — before/after values preserved`)}catch(error){toast(error.message)}finally{close()}}
function filterRows(input,body){const q=input.value.toLowerCase();$$('tr',body).forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}
function refreshCampaignAchievement(){const totalTarget=LAUNCHES.reduce((sum,item)=>sum+item.targetVolume,0),totalCurrent=LAUNCHES.reduce((sum,item)=>sum+Math.min(item.currentVolume,item.targetVolume),0),overall=campaignAchievement(totalCurrent,totalTarget);LAUNCHES.forEach(item=>{const card=$(`[data-campaign-product="${item.id}"]`),achievement=campaignAchievement(item.currentVolume,item.targetVolume);if(!card)return;card.querySelector('header>span').textContent=`${achievement.toFixed(1)}%`;card.querySelector('[data-product-achievement]').textContent=`${achievement.toFixed(1)}%`;card.querySelector('[data-product-achievement-bar]').style.width=`${achievement}%`;card.querySelector('[data-product-achievement-units]').textContent=`${fmt(Math.min(item.currentVolume,item.targetVolume))} / ${fmt(item.targetVolume)} units`});$('#campaign-overall-value').textContent=`${overall.toFixed(1)}%`;$('#campaign-overall-bar').style.width=`${overall}%`;$('#campaign-overall-units').textContent=`${fmt(totalCurrent)} of ${fmt(totalTarget)} units`;state.plan=applyLaunchScenario(state.basePlan,state.solutionVariant,state.reviewOptions)}
function bindView(){
  $$('[data-jump]').forEach(x=>x.onclick=()=>setView(x.dataset.jump));
  $$('[data-launch-id]').forEach(card=>card.onclick=()=>{const id=card.dataset.launchId;if(state.selectedLaunches.has(id)&&state.selectedLaunches.size===1){toast('Keep at least one launch selected');return}state.selectedLaunches.has(id)?state.selectedLaunches.delete(id):state.selectedLaunches.add(id);state.lastLaunchId=id;state.solutionVariant=0;state.plan=applyLaunchScenario(state.basePlan,0,state.reviewOptions);render();setTimeout(()=>{$(`[data-launch-id="${id}"]`)?.classList.remove('just-selected');state.lastLaunchId=null},850)});
  $('#apply-launches')?.addEventListener('click',buildManufacturingPlan);
  $$('[data-campaign-field]').forEach(input=>input.addEventListener('input',event=>{const card=event.currentTarget.closest('[data-campaign-product]'),item=LAUNCHES.find(product=>product.id===card?.dataset.campaignProduct);if(!item)return;let value=Math.max(event.currentTarget.dataset.campaignField.includes('Volume')?0:1000,Number(event.currentTarget.value)||0);if(event.currentTarget.dataset.campaignField!=='targetVolume')value=Math.min(value,item.targetVolume);item[event.currentTarget.dataset.campaignField]=value;item.volume=`${Math.round(item.targetVolume/1000)}K units`;item.moq=item.targetMoq;refreshCampaignAchievement()}));
  $('#campaign-moq-mode')?.addEventListener('change',event=>{state.moqMode=event.target.value;state.plan=applyLaunchScenario(state.basePlan,state.solutionVariant,state.reviewOptions);toast(state.moqMode==='fixed'?'Target MOQ will be enforced as a fixed constraint':'MOQ will be optimized within supported limits')});
  const drawer=$('#launch-drawer'),closeDrawer=()=>drawer?.classList.add('hidden');
  $('#create-launch')?.addEventListener('click',()=>{drawer?.classList.remove('hidden');setTimeout(()=>$('#new-launch-form input[name="name"]')?.focus(),80)});
  $('#close-launch-drawer')?.addEventListener('click',closeDrawer);$('#close-launch-drawer-x')?.addEventListener('click',closeDrawer);$('#cancel-new-launch')?.addEventListener('click',closeDrawer);
  $('#new-launch-form')?.addEventListener('submit',event=>{event.preventDefault();const launch=customLaunchFromForm(event.currentTarget);if(!launch.name||!launch.sku){toast('Enter a campaign name and SKU');return}closeDrawer();toast(`${launch.name} saved as a future campaign draft`)});
  const strategyKeys={Overview:'overview','Key Metrics':'metrics','Line Utilization':'utilization','Product Mix':'mix',Changeovers:'changeovers',Inventory:'inventory','Cost Breakdown':'costs'};
  $$('.subtabs button').forEach(button=>{const key=button.dataset.strategyTab||strategyKeys[button.textContent.trim()];if(key)button.onclick=()=>{state.strategyTab=key;render()}});
  const explainKeys={'Transition Reasoning':'transition','MOQ Reasoning':'moq','PV Reasoning':'pv','Cost Breakdown':'cost','Rule Impact':'rules'};
  $$('.view-tabs button').forEach(button=>{const key=button.dataset.explainTab||explainKeys[button.textContent.trim()];if(key&&!button.dataset.modelTab)button.onclick=()=>{state.explainTab=key;render()}});
  $('#compare-scenarios')?.addEventListener('click',()=>setView('scenario'));
  $('#sku-search')?.addEventListener('input',e=>filterRows(e.target,$('#sku-body')));
  $$('[data-pv-product]').forEach(element=>element.addEventListener('click',()=>{state.selectedPVProduct=element.dataset.pvProduct;render()}));
  $('#moq-search')?.addEventListener('input',e=>filterRows(e.target,$('#moq-body')));
  $$('[data-moq-product]').forEach(element=>element.addEventListener('click',()=>{state.selectedMOQProduct=element.dataset.moqProduct;render()}));
  $('#moq-slider')?.addEventListener('input',e=>$('#moq-value').textContent=`${e.target.value}%`);
  $('#solve-scenario')?.addEventListener('click',()=>solve({moq_adjustment:Number($('#moq-slider').value),strict_due_dates:$('#strict-due').checked}));
  $('#review-moq')?.addEventListener('input',e=>$('#review-moq-value').textContent=`${Number(e.target.value)>0?'+':''}${e.target.value}%`);
  $('#resolve-review')?.addEventListener('click',()=>solve(readReviewOptions()));
  $('#resolve-constraints')?.addEventListener('click',()=>solve());
  $('#constraint-resolve-shortcut')?.addEventListener('click',()=>$('#resolve-constraints')?.click());
  $('#save-scenario')?.addEventListener('click',()=>toast('Scenario saved in this browser session'));
  $$('[data-quick]').forEach(x=>x.onclick=()=>{const slider=$('#moq-slider');slider.value=x.dataset.quick;$('#moq-value').textContent=`${x.dataset.quick}%`;toast('Quick scenario loaded')});
  $('#constraint-search')?.addEventListener('input',e=>{state.constraintSearch=e.target.value.toLowerCase();$('#constraint-body').innerHTML=constraintRows();bindConstraintToggles()});
  $('#constraint-type')?.addEventListener('change',e=>{state.constraintType=e.target.value;$('#constraint-body').innerHTML=constraintRows();bindConstraintToggles()});
  bindConstraintToggles();
  $$('[data-constraint-value]').forEach(select=>select.onchange=()=>{const item=state.plan.constraints.find(c=>c.id===select.dataset.constraintValue);item.value=select.value;const baseItem=state.basePlan.constraints.find(c=>c.id===item.id);if(baseItem)baseItem.value=select.value;toast(`${item.name} updated — resolve the plan to apply`) });
  $('#approve-plan')?.addEventListener('click',()=>{state.approved=true;render();toast('Plan submitted for business approval')});
  $('#browse-data')?.addEventListener('click',()=>toast('Synthetic POC: file selection is disabled'));
  $('#save-settings')?.addEventListener('click',()=>toast('Module 2 settings saved'));
  $$('[data-model-tab]').forEach(button=>button.onclick=()=>{if(button.dataset.modelTab==='0')return;$$('[data-model-tab]').forEach(x=>x.classList.toggle('active',x===button));$('#model-panel').innerHTML=panel(button.textContent,`<div style="min-height:360px;display:grid;place-items:center;text-align:center"><div><span style="font-size:40px;color:var(--orange)">⚙</span><h2>${button.textContent}</h2><p>Interactive configuration is available in the production implementation. Synthetic defaults are active for this POC.</p><button class="m2-secondary">View current configuration</button></div></div>`)});
}
function bindConstraintToggles(){$$('[data-constraint]').forEach(button=>button.onclick=()=>{const item=state.plan.constraints.find(c=>c.id===button.dataset.constraint);item.active=!item.active;const baseItem=state.basePlan.constraints.find(c=>c.id===item.id);if(baseItem)baseItem.active=item.active;render();toast(`${item.name} ${item.active?'enabled':'disabled'} — resolve the plan to apply`)})}

async function init(){
  const authenticated=sessionStorage.getItem('pulse_authenticated')==='true'||localStorage.getItem('pulse_authenticated')==='true';
  if(!authenticated){window.location.href='/';return}
  const email=sessionStorage.getItem('pulse_user_email')||localStorage.getItem('pulse_user_email')||'Demo user';$('#m2-account-email').textContent=email;$('#m2-account-button').textContent=email.split('@')[0].split(/[._-]/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'SM';
  $('#m2-sidebar').addEventListener('click',event=>{const button=event.target.closest('.m2-nav button[data-view]');if(!button)return;event.preventDefault();setView(button.dataset.view)});
  $('#module-switch').onclick=()=>$('#module-menu').classList.toggle('hidden');
  $('#m2-mobile-nav').onclick=()=>$('#m2-sidebar').classList.toggle('open');
  $('#m2-account-button').onclick=()=>$('#m2-account-menu').classList.toggle('hidden');
  $('#m2-logout').onclick=()=>{sessionStorage.clear();localStorage.removeItem('pulse_authenticated');localStorage.removeItem('pulse_user_email');window.location.href='/'};
  $('#solve-plan').onclick=()=>state.view==='review'?($('#approve-plan')?.click()||toast('Open review to approve')):state.view==='launch'?buildManufacturingPlan():state.view==='scenario'?solve(readReviewOptions()):solve();
  $('#site-select').onchange=e=>toast(`Site changed to ${e.target.value}`);$('#horizon-select').onchange=e=>toast(`Planning horizon changed to ${e.target.value}`);
  try{const response=await fetch('/api/module2/plan');if(!response.ok)throw new Error();state.basePlan=await response.json();state.plan=applyLaunchScenario(state.basePlan);setView('launch')}catch(_){$('#m2-content').innerHTML='<div class="m2-loading"><p>Module 2 synthetic plan is unavailable.</p></div>'}
}
init();
